window.HB_TR["nehemiah"]["ks"]=["1. ہخالیاہ سُند نیچو نحمیاہ سُند کلام۔ تہٕ یہ سپُد وُہمہِ ؤریس منز وُہمہِ ؤریس منز ییلہ بہٕ شوشن محلس منز اوسس،\n2.\\tسُہ حَنانی یُس میون اکھ بٲے آو سُہ تہٕ یہوداہ ہٕندِس مردس سٍتـ̡ آو۔ تہٕ میہ پرژھ تمن یہودین متعلق، یِم قید نِش باقٕے ٲسۍ، تہٕ یروشلمس متعلق۔\n3. تہٕ تِمو ووٚن میہ زِ یُس صوبس مَنٛز قٲد روزان چھُ، سُہ چُھ سٮ۪ٹھاہ مصیبت تہٕ ملامت ہُند شکار: یروشلمٕچ دیوار تہِ چھِ پھُٹمٕژ، تہٕ اَمہ ہٕندِس دروازس چھِ نارٕ سٍتـ̡ زالنہٕ آمٕتۍ۔\n4. تہٕ ییلہ میہ یہ لفظ بوز، بہٕ بیوٹھ تہٕ رووُن، تہٕ کٔرٕن {کیٚنٛہہ} دۄہن ہُند ماتم تہٕ روزٕ کورُن، تہٕ آسمانہٕ کِس خداہس برونہہ کُن دُعا کٔرٕن،\n5. تہٕ وۆنُن، اے خداوند، اے آسمانُک خدا، عظیم تہٕ خوفناک خدا، یُس تِمن لوکن خٲطرٕ عہد تہٕ رحمت تھاوان چُھ، یُس أمِس محبت کران چُھ تہٕ تٔمۍ سٕندِس حکمس پیٹھ عمل کران چُھ:\n6. پَنٕنـ̡ کَن کٔرِو وُنہِ توجہ دِنہٕ تہٕ پَنٕنـ̡ أچھ یێلہٕ یێلہِ تێلہِ پَنٕنـ̡ پَنٕنـ̡ خادم سٕنز دُعا بوزِتھ، یُس بہٕ وُنـ̡ دۅہہٕ رات، بنی اِسرٲیلـ̡ ہٕندِس خادمَن ہٕندِ خٲطرٕ دُعا کران چُھس، تہٕ کٔرِو اسرٲیلـ̡ ہٕندِس گۅنہہ ہُند اقرار یُس أسـ̡ تہٕ تۅہہِ سٍتـ̡ گۅنہٕ کورمُت چُھ، یُس أسـ̡ تہٕ میٲنِس مٲلہِ سٕندِس گرس سٍتـ̡ چُھہ گۅنہٕ گونہٕ کورمُت۔\n7.\\tاسہِ چُھہ توے سٍتـ̡ سٮ۪ٹھاہ بدعنوانی سٍتـ̡ حُکمن تہٕ نہ قونونن تہٕ تِمن فیصلن ہُند عمل کورمُت یُس ژے پننِس خادم موسیٰ سُند حُکُم دِژمُت چُھ۔\n8. یاد تھاوُن، بہٕ چُھس ژے سُہ کلام یاد تھاوُن یُس ژے پننِس بندس موسیٰ ہس حکم دِژمُت چھُ، یێلہِ تہٕ ژے گٔژھِو ژے قومن مَنٛز پھٔہلِتھ ۔\n9.\\tمگر اگر تہۍ میانہِ کُن پھیرِو، تہٕ میٲنۍ حُکمن پیٹھ عمل کٔرِو، تہٕ تِم کٔرِو۔ یێلہِ تہِ یێلہِ تہٕ یێلہِ تہِ یِم آسمانہٕ کِس اندِس حصس تام کڈنہٕ آمٕتۍ، {توتہِ} بہٕ کٔرٕ تِم تتہِ سٍتـ̡ جمع کٔرِتھ، تہٕ اَننہٕ تِمن تتھ جایہِ یُس مے پنُن ناو تھاونہٕ خٲطرٕ ژٲرمُت چُھ۔\n10. وۅنۍ چِھ یِم تُہٕندِس خادم تہٕ تُہٕندِس لوُک، یِم ژے پنہٕ نِس زبردست طاقتہٕ سٍتـ̡ تہٕ پننہِ مضبوٗط اتھہٕ سٍتـ̡ نجات دِژمٕژ چھِ۔\n11.\\tاے خداوند، بہٕ چُھس ژے گُزٲرِتھ زِ وۅنۍ گژھہِ پنٕنـ̡ خادم سٕنزِ دعاہٕ سٍتـ̡ تہٕ پننین خادمَن ہٕنزِ دُعاہس سٍتـ̡ توجہ دِنہٕ، یِم تُہٕندِس ناوٕ سٍتـ̡ خوفزدہ گژھُن یژھان چھِ، تہٕ بہٕ چُھس ژے سٕندِس خادمَس سٍتـ̡ دُعا دِوان تہٕ أمِس شخصہٕ سٕندِس نظرس مَنٛز رحمت۔ تکیازِ بہٕ اوسس بادشاہ سُند پیالہ بردار۔","1.\\tتہٕ یہ سپُد نِسانس مَنٛز، بادشاہ ارتخسرکس سٕندِس وُہمہِ ؤریس مَنٛز، {یہ} شراب {اوس} أمِس برونہہ کُن، تہٕ مے تُل شراب، تہٕ دِژُن بادشاہس شراب۔ وۅنۍ اوس نہ میہ امۍ سنزِ موجودگی منز غمگین۔\n2.\\tکیازِ ووٚن بادشاہن میہ زِ ژیہ کیازِ چھکھ نہ بیمار وچھتھ ژیہ بُتھ غمگین؟ یہِ {چھُ} نہٕ دِلُک غم۔ امہ پتہ اوسس میہ سیٹھا کھوژان،\n3. تہٕ ووٚنُن بادشاہس زِ بادشاہ گژھہِ ہمیشہٕ زندٕ: میون بُتھ کیازِ گژھہِ نہٕ غمگین، ییلہ شہر، میانین مٲلن ہٕندٮ۪ن قبرن ہٕنز جاے تہٕ تِمن ہٕندِس دروازس نارس سٍتۍ زٲلِتھ آسہِ۔\n4. پتہٕ ووٚن بادشاہن مے زِ ژٕ کتھ خٲطرٕ چُھکھ درخواست کران؟ چنانچہ کٔر میہ آسمانہ کس خدایس دُعا۔\n5. تہٕ مے ووٚن بادشاہس زِ اگر بادشاہس خۅش گژھہِ، تہٕ اگر چانہِ خادمَس تہٕ تۅہہِ ہٕندِس نظرس منز احسان میلہِ، تہٕ ژے سوز مے یہوداہ، میانین مٲلن ہٕندِس قبرن ہٕندِس شہرس منز، یُتھ بہٕ یہِ تعمیر کٔرِتھ۔\n6.\\tتہٕ بادشاہن ووٚن میہ (ملکہ تہِ أمِس سٍتـ̡ بِہِتھ،) تُہند سفر کٲتِس کالس روزِ؟ تہٕ ژٕ کر واپس؟ لہذا اوس بادشاہس مےٚ سوزنہٕ خٲطرٕ خۄش۔ تہٕ میہ کوٚر تس اکھ وقت۔ {ملکہ: ہیب۔ زنانہٕ}\n7. اَمہِ علاوٕ ووٚن میہ بادشاہس زِ اگر بادشاہ خۅش آسہِ، دٔریاوٕ اپارِ گورنرن دِنہٕ یِن مے چِٹھہِ دِنہٕ، یُس بہٕ یہوداہ یِنس تام واتناوُن۔\n8.\\tتہٕ بادشاہ سٕندِس جنگلُک رٲچھ کرن وٲلِس آسافس اکھ چِٹھہِ، یُس سُہ میہ محل کِس دروازس خٲطرٕ تہٕ شہرٕچ دیوار خٲطرٕ تہٕ تتھ مکانس خٲطرٕ یُس بہٕ اژُن آسہِ۔ تہٕ بادشاہن دیت میہ خدایہ سٕندِ نیک اتھہٕ مطٲبق۔\n9.\\tپتہٕ آو بہٕ دریاوس اپارِ گورنرن نِش، تہٕ دِژُن تِمن بادشاہ سٕنز چِٹھۍ۔ وۄنۍ اوس بادشاہن فوجٕکۍ کپتان تہٕ گُرۍ سوار مےٚ سۭتۍ سوٗزمٕتۍ۔\n10.\\tییلہ سنبلات حورونی تہٕ ٹوبیاہ خادم عمونین یہِ بوز، تِمن گۆو سٮ۪ٹھاہ غم زِ اَکھ انسان آو بنی اسرٲیلِچ خیر ژھارنہٕ خٲطرٕ۔\n11. تہٕ بہٕ ووت یروشلم، تہٕ اتہِ روٗد تریہ دۅہ۔\n12. تہٕ بہٕ ووت رٲژ وۅتھ، بہٕ تہٕ کینہہ نفر پانس سٍتۍ۔ نہ ووٚن میہ {کٲنسہ} انسانس یُس میانہِ خدایہ یروشلمس منز میٲنس دلس منز تھوومُت اوس، تہٕ نہ اوس میہ سٍتۍ کانہہ درندٕ، سوائے سُہ جانور یُس بہٕ سوار اوس۔\n13.\\tتہٕ بہٕ دراو رٲژ وادی ہٕندِس دروازس پیٹھ، ڈریگن کُنہِ کُنہِ برونہہ تہٕ گوبر بندرگاہِ کُن، تہٕ وُچھمُت یروشلمٕچ دیوار، یِم پھُٹمٕژ ٲس تہٕ یِمن ہٕندِس دروازس ٲس نارٕ سٍتـ̡ زٲلِتھ۔\n14. پتہٕ ووت بہٕ چشمہٕ کِس دروازس کُن، تہٕ بادشاہ سٕندِس تالابس کُن: مگر {اتہِ} ٲس نہٕ میٲنس تل درندٕ سٕندِ خٲطرٕ کانہہ جاے۔\n15.\\tپتہٕ ووت بہٕ رٲژ نالہٕ نِش تہٕ دیوار وُچھمُت، تہٕ واپس پھیُر، تہٕ وادی ہٕندِس دروازٕ کِنۍ ژاو تہٕ واپس۔\n16.\\tتہٕ حکمرانن ٲس نہٕ خبرے زِ بہٕ کوٚت گۆو، تہٕ میہ کیا کوٚر۔ نہ اوس میہ وُنیُک تام یہودین وونمُت، نہ پادٕرین تہٕ نہ رئیسن تہٕ نہ حکمرانن تہٕ نہ باقین یِم کٲم کران ٲسۍ۔\n17.\\tتێلہِ وۆن میہ تِمن وُچھمُت، یێلہِ چُھہ یُس مصیبت وُچھان چُھ، یێتھ کٔنۍ چُھہ یروشلمُک دیوار تہٕ اَمہ کِس دروازس نارٕ سٍتـ̡ زالنہٕ آمُت: یێلہِ یێلہِ أسـ̡ یروشلمُک دیوار بَناوُن، یُتھ أسـ̡ نہٕ وُنہٕ ملامت کرنہٕ یِنـ̡ ۔\n18.\\tتێلہِ وون میہ تمن پننہِ خدایہ سٕندِ اتھس مُتلق یُس میانہِ خٲطرٕ نیک اوس۔ تہٕ بادشاہ سٕندۍ لفظ تہِ یِم تٔمۍ میہ سٍتۍ کتھ کٔرمٕژ۔ تہٕ تِمو ووٚن، أسۍ تھوٚد تھوٚد تہٕ تعمیر کرٕنۍ۔ چنانچہ تِمو کٔر اَتھ {یہ} اصل {کٲم} خٲطرٕ پنٕنۍ اتھہٕ مضبوٗط۔\n19.\\tمگر ییلہ سنبلات حورونی تہٕ طوبیاہ خادم، عمونی تہٕ گیشم عربن بوز، تِمو کٔر اسہِ حقارت کرنہٕ خٲطرٕ اسہِ حقارت تہٕ حقارت کٔرِتھ وونُن، یہِ کیا چُھہ یُس تُہۍ کران چھِو؟ کیا تُہۍ کٔرِو بادشاہس خٕلاف بغاوت؟\n20.\\tتێلہِ دیُت میہ تمن جواب، تہٕ وونُن تِمن آسمانُک خدا، سُہ کرِ اسہِ ترقی۔ تێمہِ کِنۍ چُھہ أسۍ تٔمۍ سٕندِس خادمَس وۅتھان تہٕ تعمیر کٔرِتھ، مگر یروشلمس مَنٛز چُھہ نہٕ تۅہہِ کانہہ حصہٕ، نہ حق، تہٕ نہ یادگار۔","1.\\tاَمہِ پَتہٕ ووٚتھ الیاشیب، پَنٕنٮ۪ن باین پادٕرٮ۪ن سٍتـ̡ تہٕ تِمو بنوو کۅکرِ ہُند دروازٕ۔ تِمو کٔر یہِ پاکیز، تہٕ کٔرِکھ اَمیُک دروازٕ۔ میاح کِس برجس تام تہِ کوٚر تمو یہ حنانیل کِس برجس تام مقدس۔\n2. تہٕ أمِس پَتہٕ بٔنِتھ کٔر یریحا ہٕندِس انسانس ۔ تہٕ تمن پتہٕ بنوو امری سُند نیچو زکر۔ {امہ پتہٕ...: ہیب۔ تٔمۍ سٕنٛدس اتھس پیٹھ}\n3.\\tمگر گاڈِ ہُند دروازہ بنوو حسینہ سٕندِس نیچو یِمو اَمہِ سٕندِ دروازٕ تہٕ اَمہ ہٕندِ دروازٕ تہٕ تالہٕ تہٕ اَمہ سٕندِ سلاخہٕ بٔنِتھ بٔنِتھ۔\n4.\\tتہٕ یِمن پتہٕ کٔر کوز سُند نیچو یُس اوریاہ سُند نیچو میرموتھ مرمت ۔ تہٕ یِمن پتہٕ کٔر مشیزبیل سُند نیچو بریخیاہ سُند نیچو مشہلام۔ تہٕ تِمن پتہٕ کٔر بانا سُند نیچو زادوک مرمت۔\n5. تہٕ تمن پتہٕ کٔر ٹیکویٹس مرمت۔ مگر تِہٕندِس رئیسَس چھِنہٕ پنٕنۍ گردن پننِس آقا سٕنزِ کامہِ سٍتـ̡ تھپھ کٔرِتھ۔\n6.\\tامہِ علاوٕ کٔر پرانہِ دروازس پسہِ سُند نیچو یہویادا، تہٕ بیسودیہ سُند نیچو مشُلَم مرمت کرنہٕ۔ تمو لگٲو امکۍ بیمہٕ، تہٕ امکۍ دروازٕ، تہٕ تالہٕ تہٕ امہٕ کِس سلاخہٕ لگٲو۔\n7.\\tتہٕ تِمن پتہٕ کٔر میلاتیہ گِبونی تہٕ جِبیونٕکۍ مرد تہٕ مِزپاہ سٕندِس تختس پیٹھ بِہتھ دٔریاوٕ کِس اَتھ طرفہٕ گورنر سٕندِس تختس پیٹھ۔\n8.\\tأمِس پَتہٕ کٔر سونارَن ہُند نیچو عزِیل، یُس ہرہیا سُند نیچو اوس۔ أمِس پتہٕ کٔر حنانیاہ یُس اپوتھیکری سُند نیچو تہِ مرمت تہٕ تِمو کٔر یروشلم وسیع دیوارس تام قلعہٕ۔ {قلعہ بندی...: یا، یروشلم تروو وسیع دیوارس تام}\n9.\\tتہٕ یِمن پتہٕ کٔر یروشلم کِس نصف حصُک حُکُمران حُور سُند نیچو رفیعیاہ مرمت۔\n10.\\tتہٕ یِمن ہٕندِس پَتہٕ کٔرِتھ کٔرٕن حروماف سُند نیچو یِدایاہ تٔمۍ سٕندِس گرس سٍتـ̡ تہِ مرمت کرنہٕ۔ تہٕ أمِس پتہٕ کٔر حشبنیاہُک نیچو حتوش مرمت۔\n11.\\tحاریم سُند نیچو ملکیجاہ تہٕ پہتھموآب سُند نیچو ہاشوب کٔر بیاکھ ٹُکرٕ تہٕ بھٹن ہُند مینار مرمت۔ {باقی...: ہیب۔ دۆیم پیمائش}\n12.\\tتہٕ أمِس پتہٕ کٔر یُس یروشلم کِس نصف حصُک حُکُمران ہالوہیش سُند نیچو شلوم، سُہ تہٕ تٔمۍ سٕنزِ کورِ ہٕنز مرمت کٔرِتھ۔\n13. وادی ہٕندِس دروازس سٍتـ̡ کٔر حنون تہٕ زانواہ کین بسکینن ہٕنز مرمت۔ تمو بنٲو یہٕ تہٕ امکۍ دروازٕ، تالہٕ، تہٕ امچ سلاخ، تہٕ دیوارس پیٹھ اکھ ساس کیوبٹ لگٲوکھ گوبر کس دروازس تام۔\n14.\\tمگر گُرِ ہٕندِس دروازس سٍتـ̡ کٔر رِچاب سٕندِس نیچوِس ملکیاہ سٕنز مرمت یُس بیت ہکریم کِس حصس ہُند حُکُمران اوس۔ تم بنوو یہٕ، تہٕ امکۍ دروازٕ، تالہٕ تہٕ امچ سلاخہٕ لگٲو۔\n15.\\tمگر چشمہٕ کِس دروازس سٍتـ̡ کٔر مزپہٕ کِس أکِس حصس ہُند حکمران کولہوزہ سُند نیچو شالُن مرمت۔ تٔمۍ بنوو یہٕ تہٕ کور تہٕ امہٕ کِس دروازٕ، تالہٕ، تہٕ امہٕ کِس سلاخ، تہٕ بادشاہ سٕندِس باغس نِش سیلواہ کِس تالابٕچ دیوار، تہٕ ڈیوڈ شہرٕ پیٹھٕ بۄن گژھن واجنہِ ہیرن تام۔\n16.\\tأمِس پَتہٕ کٔر بیتھزور کِس نصف حصُک حُکُمران ازبُک نیچو نحمیاہ سٕندِس مقبرس سٍتـ̡ داؤد سٕندِس قبرس تہٕ بَناونہٕ آمٕژ تالابس تام، تہٕ طاقتور سٕندِس گرس تام۔\n17.\\tتٔمۍ سٕندِس لٔوِس مَرمَتھ کٔرِتھ بنی سُند نیچو۔ أمِس پتہٕ کٔر کیلہ کِس نصف حصُک حُکُمران حشبہیاہ ہٕنز مرمت۔\n18.\\tتٔمۍ سٕندِ پَتہٕ کٔر پننین باین ہٕنز مرمت ، ہیناداد سٕندِس نیچوِس باواے یُس کیلہ کِس نصف حصُک حُکُمران اوس۔\n19.\\tتہٕ أمِس سٍتـ̡ کٔر یشوع سُند نیچو عزر مرمت، یُس مزپاہُک حاکم اوس، یُس دیوارس پیٹھ ہتھیار خانس تام کھسنہٕ وِزِ بیاکھ ٹُکرٕ اوس۔\n20.\\tأمِس پَتہٕ کٔر زبایی سٕندِس نیچِوِ باروخ سٍتـ̡ دوٚیِم ٹُکرٕ سٍتـ̡ دیوارٕ کِس پھیرس پیٹھٕ اِلیاشیب سٕندِس گرٕ کِس دروازس تام۔ {زبائی: زکائی تہِ ونان چھِ}\n21.\\tأمِس پتہٕ کٔر اریجاہ سُند نیچو میرموتھ بیاکھ اکھ ٹُکر، الیاشیب سٕندِ گرٕ کِس دروازٕ پیٹھٕ الیاشیب سٕندِس گرٕ کِس اندس تام۔\n22.\\tتہٕ أمِس پَتہٕ کٔرٕکھ پادٕرۍ، میدانٕکۍ مرد۔\n23.\\tأمِس پتہٕ کٔر بینجمن تہٕ ہشوب تِہندِس مکانس خٕلاف۔ أمِس پتہٕ کٔر عزریاہ سُند نیچو ععُریاہ سٕندِس مکانس سٍتـ̡ مرمت کرنہٕ۔\n24.\\tأمِس پَتہٕ کٔر حناد سٕندِس نیچوِس بِنُوئی سٕندِس بیاکھ ٹُکرٕ، عزریاہ سٕندِ گرٕ پیٹھٕ دیوارٕ کِس پھیرس تام، حتیٰ کہ کونس تام۔\n25.\\tپالال یُس اُزایی سُند نیچو چھُ، تہٕ سُہ مینار یُس بادشاہ سٕندِس تھدِ مکانس منزٕ نیران چھُ، یُس جیل کِس دربارس منز اوس۔ تٔمِس پتہٕ پَدِیاہ پَروُش سُنٛد نیٚچُو۔\n26.\\tامہِ علاوہ اوس نیتھینم اوفیلس منز روزان، مشرقس کُن آبہٕ کس دروازس پیٹھ تہٕ نیبر کُن بٔرِتھ مینارس تام۔ {dwellt...: یا، یُس اوفیلس منز روزان اوس، مرمت کٔرِتھ} {اوفیل: یا، ٹاور}\n27. تمن پتہٕ کٔر ٹیکویٹس بیاکھ اکھ ٹُکرٕ مرمت، یُس عظیم مینارس پیٹھ اوس، یوتام زِ اوفیل کس دیوارس تام۔\n28.\\tگُرِ ہٕندِس دروازس پیٹھٕ کٔر پادٕرۍ، پرٮ۪تھ کانہہ اوس پننِس مکانس پیٹھ۔\n29.\\tیِمو پتہٕ کٔر اِمر سٕندِس نیچوِس زادوک سٕندِس مکانس خٕلاف۔ امہِ پتہٕ کٔر مشرقی دروازُک رٲچھ کرن وٲلِس شیخانیا سُند نیچو شمعیاہ تہِ مرمت۔\n30.\\tأمِس پَتہٕ کٔر شلیمیاہ سُند نیچو حنانیاہ تہٕ زالاف سُند شیٚیِم نیچو حنون بیاکھ ٹُکر۔ امہِ پتہٕ کٔر بریخیاہ سُند نیچو مشُلام پننِس کمرس منز مرمت۔\n31.\\tأمِس پَتہٕ کٔر ملچیاہ سُند نیچو نیتھینیمس تہٕ سوداگرن ہٕنزِ جایہ تہٕ دروازٕ میفکادس نِش تہٕ کونہٕ کِس کھسنہٕ کِس مقامس تام۔ {گَژھُن...: یا، کارنر چیمبر}\n32.\\tتہٕ کُنہِ دروازس تام گٔیہِ سونارن تہٕ سوداگرن ہٕنز مرمت۔ {گَژھُن...: یا، کارنر چیمبر}","1.\\tمگر سپد یہ زِ ییلہ سنبلاتن بوز زِ اسہِ چھیہ دیوار تعمیر کٔرمٕژ، سُہ گوٚو شرارت تہٕ کوٚرُن یہودین ٹھٹھہٕ۔\n2. تہٕ تٔمۍ کٔر پننین باین تہٕ سامریہ ہٕندِس لشکرس برونہہ کُن کتھ تہٕ وونُن، یِم کمزور یہودی کیا چِھہ؟ کیا تِم کٔرِن پنُن پان مضبوٗط؟ کیا تِم چھا قربانی؟ کیا تِم کٔرِوا أکِس دۄہس منٛز ختم؟ کیا تِم کٔرِتھ زٲلِتھ کٔنہِ کُ {fortify...: Heb. پانَس کُن تراوُن}\n3.\\tوۅنۍ اوس طوبیہ عمونیت تٔمۍ سٕندِ دٔسۍ تہٕ ووٚنُن، یُس تہِ تِم بناوان چھِ، یێلہِ پٲٹھـ̡ پى۪ٹھ\n4. اے سانہِ خدایہ بوزو۔ تکیازِ أسۍ چھِ حقارت کرنہٕ آمٕژ: تہٕ تِہُند ملامت چھُ پننِس کلس پیٹھ پھیران، تہٕ دِوان تِمن قید کِس سرس مَنٛز شِکار: {حقارت: حب۔ despite}\n5.\\tتہٕ تِہٕندِس گناہ ہٕندِس گۅنہٕ سٍتـ̡ ژٔٹِتھ تہٕ یِمن ہُند گۅناہ گژھہِ نہٕ پانس برونہہ کُن ژٹنہٕ، تکیازِ تِمو چُھہ تۅہہِ سٍتـ̡ معمارن برونہہ کُن شرارت دِژمُت۔\n6.\\tیتھہ پاٹھۍ بنوو اسہِ دیوار۔ تہٕ سورے دیوار ٲس اتھ نصفس تام رلاونہٕ آمٕژ: تکیازِ لوٗکن اوس کٲم کرنُک ذہن۔\n7.\\tمگر سپد سپد ییلہ سنبلات تہ طوبیہ، عربو تہ عمونیو تہ اشدودیو بوز زِ یروشلمچ دیوار چھیہ بنیمژ، {تہِ} زِ یہ پھیپھ گٔیہِ رُکاونہٕ آمٕژ، تمہ پتہ گٔے تم واریاہ شرارت، {آیہ بنوومُت: حب۔ کھسُن}\n8. تہٕ کٔرٕکھ یِمو سارِنٕے رٔلِتھ یِنہٕ خٲطرٕ یِنہٕ خٲطرٕ تہٕ اتھ رُکاوٹ کرنہٕ خٲطرٕ۔ {رُکاوٹ کرُن...: ہیب۔ اَتھ مَنٛز غلطی کَرنہٕ خٲطرٕ}\n9. توتہِ کٔر أسۍ پننِس خدایس سٍتـ̡ دُعا تہٕ تِمن ہٕندِ مۅکھہٕ دۅہ راتس پٲٹھـ̡ نظر تھاوُن۔\n10.\\tتہٕ یہوداہ ووٚن زِ بوجھ تُلنہٕ والٮ۪ن ہُند طاقت چُھ ختم گومُت، تہٕ {اتہِ} چُھ واریاہ فضلہٕ۔ تاکہ أسۍ ہیوٚک نہٕ دیوار تعمیر کٔرِتھ۔\n11. تہٕ سانٮ۪و مُخٲلِفن ووٚن زِ تِمن گژھِ نہٕ پتاہ تہٕ نہ وُچھِن، یوٚت تام نہٕ أسۍ تِمن درمِیان اژِتھ تہٕ تِمن مارِو، تہٕ کٲم بند کرٕنۍ۔\n12. تہٕ سپُد یہِ زِ یێلہِ یِم یہودی یِم تِمن نِش روزان ٲسۍ، تِمو ووٚن اسہِ دَہ لٹہِ، سارِنٕے جاین پیٹھٕ یێلہِ یێلہِ تُہۍ اسہِ نِش واپس۔ {سارِنٕے پیٹھ...: یا، زِ سارِنٕے جاین پیٹھٕ گژھِو اسہِ نِش واپس}\n13.\\tلہذا تھوو میہ دیوارس پٔتۍ کنہِ بنمین جاین پیٹھ، تہٕ تھزرن جاین پیٹھ، میہ تہِ تھووُن لُکن ہٕندِس عیالس پتہٕ تلوار، نیزٕ تہٕ کمانہٕ سٍتۍ۔ {منز...: ہیب۔ جایہِ ہٕندِس بٔنِمِس حصس منز، وغیرہ}\n14.\\tتہٕ بہٕ وُچھمُت تہٕ ووٚتھ تہٕ ووٚتھ رئیس، حُکُمران تہٕ باقٕے لُکن وونُن، یِمن نِش گژھ نہٕ کھوژُن، خداوند یاد تھاوُن، یُس عظیم تہٕ خوفناک چُھ، تہٕ پننین باین ، پننین نیچوین تہٕ کورِن، زنانہٕ تہٕ گرن خٲطرٕ لڑُن۔\n15.\\tتہٕ سپُد ییلہ سانین دشمنن بوز زِ اسہِ ٲس یہ خبر تہٕ خداین اوس تِہُند مشورٕ ناکام کورمُت، زِ أسۍ سارِوٕے دیوارس کُن واپس، پرٮ۪تھ کانہہ پننہِ کامہِ خٲطرٕ۔\n16.\\tتہٕ اَمہِ وقتہٕ پتہٕ سپُد یہِ سپدُن، {یہ} میانیو نصف نوکرو کامہِ منز کٲم کٔرِتھ، تہٕ یِمو منزٕ باقٕے نصف نصفس منز ٲس نیزٕ، ڈالہٕ تہٕ کمان تہٕ ہیبرجن دۄشوے رٔٹۍ۔ تہٕ حکمران ٲسۍ یہوداہ کِس سارِنٕے گرس پتھ کُن۔\n17.\\tتِم یِم دیوارس پیٹھ تعمیر کٔرِتھ، تہٕ تِم یِم بور تُلِتھ، تِمو سٍتـ̡ یِم أکِس اتھہٕ سٍتـ̡ کٲم کٔرِتھ، تہٕ دۆیمہِ اتھہٕ سٍتـ̡ ہتھیار تھاوان۔\n18.\\tمعمارن ہٕندِ خٲطرٕ، پرٮ۪تھ کٲنٛسہِ ٲس پنٕنۍ تلوار پانس سٍتۍ گٔنڈِتھ، تہٕ {یِتھ} بناونہٕ آمُت۔ تہٕ سُہ یُس ٹرمپیٹ وُن اوس میہ سٍتـ̡ ۔ {تٔمۍ سٕندِ طرفہٕ: ہیب۔ تٔمۍ سٕندِس کمرس پیٹھ}\n19.\\tتہٕ مے وون رئیسن تہٕ حکمرانن تہٕ باقٕے لوٗکن زِ یہ کٲم چھیہ عظیم تہٕ بٔڈ، تہٕ أسۍ چھِ دیوارس پیٹھ الگ گٔمٕتۍ، اکھ أکِس نِش دور۔\n20.\\tکَمہِ جایہِ چُھہ بُرٕچ آواز بوزان، تتہِ کٔرِو اسہِ سٍتـ̡\n21.\\tتہ کٔر اسہِ کامہِ منز محنت: تہٕ یِمو منزٕ ٲسۍ نصف نٮ۪صٕر صُبحہ کھسنہٕ پیٹھٕ تارکھ ظٲہِر گژھنس تام نیزٕ رٔٹِتھ۔\n22. یتھے پٲٹھـ̡ وون میہ لوکن سٍتـ̡ یێلہِ پۯاوُن زِ پرٮ۪تھ کانہہ شخص گژھہِ پننِس خادمس سٍتـ̡ یروشلمس مَنٛز روزُن، یُتھ رٲژ گژھن اسہِ رٲچھ کٔرِتھ تہٕ دۅہہٕ محنت کرٕنـ̡ ۔\n23.\\tتێلہِ نہ میہ تہٕ نہ میانیو بٲے تہٕ نہ میٲنۍ نوکر تہٕ نہ میہ پَتہٕ یِنہٕ والہِ رٲچھ کرن وٲلۍ، اسہِ منزٕ کُنہِ تہِ کُنہِ تہِ کُنہِ پَلَو ترٲوِتھ تہٕ سارِوٕے کٔر یِم چھلنہٕ خٲطرٕ ترٲومٕتۍ۔ {بچٲوِتھ...: یا، پرٮ۪تھ کانٛہہ گوٚو آبہٕ خٲطرٕ پنُن ہتھیار ہٮ۪تھ}","1. تہٕ لُکن تہٕ تِہنزن زنانن ہٕندِ بٲے یہودین خلاف گٔیہٕ سٮ۪ٹھاہ فریاد ۔\n2.\\tتِکیازِ أسۍ چھِ یِمن ہٕندِ خٲطرٕ مَکٲے تُلِتھ، یُتھ أسۍ کھٮ۪وان تہٕ زِندٕ روزان چھِ۔\n3.\\tکینہہ تہِ ٲسۍ ونان زِ اسہِ چھہِ پنٕنۍ زمین، انگور تہٕ مکانہٕ گروی تھوومٕتۍ، تاکہ أسۍ ہیوٚک مکایہ، کمی آسنہ کِنۍ۔\n4.\\tیہ تہِ اوس وننہ آمت زِ اسہِ چھہِ بادشاہ سٕندِ خراج خٲطرٕ پٲنسہٕ ہیوٚتمُت، {تہٕ سُہ چھُ سانین زمینن تہٕ انگورن ہٕندِس باغس پیٹھ۔\n5. توتہِ چُھہ سون ماز {چُھ} سانین باین ہُند ماز تہٕ سانین شُرین ہٕندِس ماز سٍتـ̡ تہٕ یێلہِ أسـ̡ پننین نیچوین تہٕ کورِ غلامی منز انان، تہٕ {سانہِ کورِ چُھہ غلامی کٔرِتھ} تہٕ {یێلہِ} چُھہ یِمن ہٕندِس فدٕ دِنہٕ خٲطرٕ {یێلہِ} سٍتـ̡ بێیہِ سٍتـ̡ تکیازِ باقین انسانن چھِ سانہِ زمینہٕ تہٕ انگور باغ۔\n6. تہٕ ییلہ میہ تہنز فریاد تہٕ یہ لفظ بوزان اوسس میہ واریاہ شرارت۔\n7. اَمہِ پَتہٕ کٔر مے پانَس سٍتـ̡ مشورٕ، تہٕ مے کٔر رئیسَن تہٕ حُکُمرن ملعزت، تہٕ وونُن تِمن سٍتـ̡ پرٮ۪تھ أکِس بٲے سٍتـ̡ رُسو۔ تہٕ مے کٔر تمن خلاف اکھ عظیم مجلس۔ {میہ کٔر مشورہ...: ہیب۔ میانہِ دِل کٔر میہ منز مشورہ}\n8.\\tتہٕ میہ ووٚن تِمن زِ أسۍ کٔر پننہِ قٲبلیت پٲٹھۍپننین بٲے یہودی یِم کافرن کٕننہٕ آمٕتۍ ٲسۍ۔ تہٕ کیا تُہۍ کٕنِکھ پنٕنۍ بٲے تہِ؟ یا یِم یِن اسہِ کٕننہٕ؟ پتہٕ تھوو تمو پنُن سکون، تہٕ لٔب نہٕ کیٚنٛہہ تہٕ جواب دِنہٕ خٲطرٕ۔\n9.\\tمیہ وونمُت، یہ چُھہ نہٕ تۅہہ کرُن: کیا ژیہ پزِ نہٕ سانہِ خدایہ سٕندِس خوفس مَنٛز پکُن، یُس سانین دُشمن ہٕندِ ملامت سٍتـ̡ چُھہ نہٕ پَکُن؟\n10.\\tبہٕ تہٕ یِتھٕ پٲٹھۍ چھُس پننین بٲے تہٕ خادمَن تہٕ یِمن ہٕندِس پٲنسہٕ تہٕ مکایہٕ ہُند وصوٗل کٔرِتھ: بہٕ چھُس دُعا کٔرِتھ زِ أسۍ تراوو یہ سود تراوُن۔\n11. بہٕ چُھس ژےٚ دُعا کران زِ تِمن ہٕنزِ زمینہٕ، تِہٕندِس انگورن، تِہٕندِس زیتون تہٕ تِمن ہٕندِس مکانس تہٕ ہتھ حِصہٕ، تہٕ مکایہ، شراب، تہٕ تیٖلُک تہٕ تِمن ہُند ہتھ حِصہٕ، یُس تُہۍ تِمن ہٕندِس نِش حٲصِل کٔرِو۔\n12.\\tاَمہ پتہٕ ووٚن تِمو زِ أسۍ کرو تِمن بحال، تہٕ تِمن ہٕندِس نِش پیٚیہِ نہٕ کانہہ ضرورت۔ تِتھے پٲٹھۍ کٔرِو أسۍ یُتھ ژےٚ وَنُن چھُ۔ اَمہ پتہٕ بُلوو پادٕرۍ تہٕ تِمن ہُند حلف زِ تِم گژھن اتھ وعدس مُطٲبق کرُن۔\n13.\\tمیہ کٔر پنُن کۅکر تہٕ وونُن، یُس نہ یہ وعدہ پورٕ کرِ، یُس نہ یہ وعدہ پورٕ کرِ، تہٕ یِتھٕ پٲٹھۍ گژھہِ سُہ ژٔٹِتھ تہٕ خٲلی کرنہٕ۔ تہٕ سارِوٕے جمٲژ ووٚن آمین، تہٕ کٔرٕکھ خداوند سٕنز تعریف۔ تہٕ لوکو کوٚر اتھ وعدس مطٲبق۔ {خٲلی: ہیب۔ خٲلی، یا، خٲلی}\n14. امہِ علاوٕ یێلہِ بہٕ یہوداہ کِس سرزمینس مَنٛز تِہُند گورنر مقرر کرنہٕ آو، وُہمہِ ؤری پیٹھٕ بادشاہ آرٹیکسرکس سٕندِس زٕ تہٕ ترہمہِ ؤریس تام، بہٕ وُہمہِ ؤری تام چُھہ نہٕ میہ تہٕ میانیو بٲے گورنر سٕنز روٹی کھیوٚمٕژ۔\n15.\\tمگر یِم سٲبقہٕ گورنر یِم میانہِ برونہہ ٲسۍ، تِمو ٲسۍ لُکن ہٕندِ خٲطرٕ ذمہ دار تہٕ تِمو نِش روٹی تہٕ شراب، ژتٲجی شیکل رۄپہٕ علاوٕ۔ آ، تِہٕندِس خادمہ تہِ چھِ لُکن پیٹھ حُکوٗمت کٔرِتھ، مگر میہ تہِ اوس نہٕ خدایہ سٕندِ خوفہٕ سٍتـ̡ ۔\n16.\\tآ، بہٕ تہِ جٲری، نہ ہیوٚت اسہِ کانہہ زمین، تہٕ میٲنۍ سٲری خادم گٔیہِ اتہِ کامہِ خٲطرٕ جمع ۔\n17.\\tامہِ علاوہ ٲسۍ میٲنس ٹیبلس پیٹھ اکھ ہتھ تہٕ پنژاہ یہودی تہٕ حکمران، تِمو علاوٕ یِم اسہِ اندۍ پکھۍ یِمن منز اسہِ نِش آمٕتۍ ٲسۍ۔\n18.\\tوۅنۍ {یہ} یُس {میانہِ خاطرہ} روزانہٕ تیار اوس کرنہٕ آمُت {اوس} اکھ داند {تہٕ} شیہ ژٲر کۅکر۔ امہ علاوہ ٲسۍ میانہِ خٲطرٕ جاناوار تیار کرنہٕ آمٕتۍ، تہٕ دہن دۅہن منز ٲسۍ اکہِ لٹہِ پرٮ۪تھ قٕسمٕچ شرابُک ذخیرٕ کرنہٕ آمٕتۍ، توتہِ اوس نہٕ میہ گورنر سٕنزِ روٹی ہٕنز ضرورت، تکیازِ غلامی ٲس یِمن لوٗکن ہٕندِس خٲطرٕ بوب۔\n19.\\tمیانہِ خدایہ سٍتـ̡ یُس میہ یِمن لوکن ہٕندِ خٲطرٕ کورمُت چُھ، تِمن سٍتـ̡ سٍتـ̡ سونٛچِو۔","1.\\tوۅنۍ سپد یہ سپد ییلہ سنبلات تہ طوبیہ تہ گیشم عرب تہ سانین باقی دشمنن بوز زِ میہ چھیہ دیوار تعمیر کٔرمٕژ، تہ اتھ منز چھہ نہ کانہہ پھُر باقی۔ (حالانکہ تمہ وقتہ ٲسۍ نہ میہ دروازن پیٹھ دروازہ لگٲومٕتۍ؛)\n2.\\tسُہ سنبلات تہٕ گیشیمن سوز میہ نِش یہ ؤنِتھ زِ آؤ، أسۍ سمکھِو اونو کِس مٲدانس منز کُنہِ گامن منز۔ مگر تِمو سونچ زِ تِم کرِ میہ شرارت۔\n3.\\tتہٕ مے سوٗزۍ تِمن نِش رسول، یہِ وَنُن زِ بہٕ چُھس اکھ بٔڈ کٲم کران، یُتھ بہٕ ہێکہٕ نہٕ وُسُن، یێلہِ بہٕ یێلہِ بہٕ یہِ تراوُن، تہٕ ژےٚ نِش یِنہٕ یِنہٕ۔\n4.\\tتوتہِ سوز یِمو اَمہ قسمہٕ پتہٕ ژورِ لٹہِ میہ نِش۔ تہٕ میہ دیت تتھۍ پٲٹھۍ تمن جواب۔\n5.\\tتمہ پتہ سوز سنبلات پنُن خادم پانژمہِ لٹہِ اتھس منز کھلہٕ چِٹھہِ ہیتھ میہ نِش۔\n6.\\tیتھ مَنٛز {اوس} لیکھنہٕ آمُت، یہِ چھُ کافرن مَنٛز وننہٕ آمُت، تہٕ گاشمو چھُ ونان زِ تُہۍ تہٕ یہودی چھِو بغاوت کرنُک خیال تھاوان، ییمہ مۅکھہٕ ژے دیوار بناوان چھُ، یُتھ زن تِہُند بادشاہ بٔنِتھ۔ {گشو: یتھ گیشم تہِ ونان چھِ}\n7. تہٕ ژے چُھہ یروشلمس مَنٛز تۅہہِ ہنز تبلیغ کرنہٕ خٲطرٕ پیغمبرن تہِ مقرر کٔرۍمٕتۍ، یہوداہَس مَنٛز چُھ اکھ بادشاہ، تہٕ وۅنۍ یِیہِ یِمو کلامَو مُطٲبِق بادشاہس وننہٕ یِنہٕ۔ لہذا آو وۅنۍ تہ کرو اسۍ رٔلتھ مشورہ۔\n8.\\tتێلہِ سوز میہ تس نِش یہ ؤنتھ زِ تۅہہ چھہ نہ یژھہ کتھ کرنہ یوان، مگر ژے چھکھ تم پننہِ دِلہٕ سٍتـ̡ بناوان ۔\n9.\\tتکیازِ یِمو سارِوٕے کٔر اسہِ خوفزدہ تہٕ یہِ ونِتھ زِ تِہٕندِ اتھہٕ گژھن کامہِ سٍتـ̡ کمزور کرنہٕ، یێلہِ یہِ گژھِ نہٕ کرنہٕ۔ تَمہِ مۄکھٕ کٔرِو مَضبوٗط مَضبوٗط۔\n10.\\tامہ پتہ ووت بہٕ مہتابیل سُند نیچو دلیاہ سٕندِس نیچو شمعیاہ سٕندِس گرس منز، یُس {اوس} بند گومُت۔ تہٕ تٔمۍ ووٚن، أسۍ رٔلِو خدایہ سٕندِس گرس منز، مندرس اندر، تہٕ أسۍ کرو مندرٕکۍ دروازٕ بند، تکیازِ تِم یِن ژےٚ مارنہِ۔ آ، رٲژ یِن تۅہہ مارنہِ۔\n11.\\tتہٕ میہ ووٚن، میہ ہیو انسان ژلُن؟ تہٕ کُس {چُھ}، یُس {آسن} یُس بہٕ {am} چُھس، پنُن زُو بچاونہٕ خٲطرٕ مندرس منز گژھِ؟ بہٕ گژھِ نہٕ اژان۔\n12. تہٕ لو، میہ وچھ زِ خداین اوس نہٕ سُہ سوزمُت۔ مگر یہ زِ تٔمۍ کٔر میانہِ خلاف یہ پیشن گویی کرنہٕ: تکیازِ طوبیہ تہٕ سنبلاتن ٲس أمس کٲم کٔرمٕژ۔\n13.\\tتێلہِ اوس تٔمۍ سٍتـ̡ کٲم کٔرمٕژ، زِ بہٕ گژھہِ کھوژُن، تہٕ کرُن، تہٕ گۅناہ کرُن، تہٕ {یُتھ} گژھن تِمن ہٕندِس بد خبرس مۅکھہٕ، یُتھ تِم کرِ میہ ملامت کرنہٕ۔\n14.\\tمیانہ خدا، توبیا تہٕ سنبلات سٍتـ̡ تِمن ہٕندِس کامہِ مُطٲبق تہٕ نبی نودیہ تہٕ باقٕے پیغمبرن مُطٲبِق، یێمہِ سٍتـ̡ میہ خوفہٕ گٔیہِ۔\n15.\\tیێلہِ گۆو دیوار اِلول کِس پٔنژمہِ دۅہس مَنٛز پنژاہ تہٕ دۅن دۅہن مُکمل کرنہٕ۔\n16.\\tتہٕ سپُد یہِ زِ ییلہ سانین سارِنٕے دُشمنن بوز، تہٕ یِمو سارِوٕے کافرو یِمو اسہِ اندۍ پکھۍ یِم چیز وُچھمٕتۍ، تِمو گٔیہِ پننین نظرن منز واریاہ پٲٹھۍ، تکیازِ تِمو اوس سمجھان زِ یہِ کٲم چھِ سانہِ خدایہ سٕندِ دٔسۍ کرنہٕ آمٕژ۔\n17.\\tتِمن دۅہن سوُزِ یہوداہ کٮ۪و رئیسو طوبیاہس واریاہ چِٹھہِ تہٕ تِمن نِش آیہ توبیاہ سٕندِ چِٹھہِ تہٕ تِمن نِش وٲتِتھ۔ {سوزمُت...: ہیب۔ تِہٕندِس چِٹھہِ گٔیہِ طوبیہس تام واتنہٕ یِنہٕ والہِ چِٹھہِ ہُند ضرب\n18.\\tکیازِ یہوداہَس مَنٛز ٲسۍ واریاہ لوٗکھ أمِس سٍتـ̡ حلف کھٲلِتھ، تکیازِ سُہ اوس آرہ سُند نیچو شیخیاہ سُند زامتُر۔ تہٕ تٔمۍ سٕنٛدِ نیچِوِ جوہانن ٲس بریخیاہ سُنٛد نیچو میشولم سٕنٛز کوٗر نِمٕژ۔\n19.\\tتہِ دِژ تِمو میانہِ برونہہ کنہِ تٔمۍ سٕندٮ۪ن نیکی عملن ہٕنز اطلاع، تہٕ کٔرٕکھ أمِس میٲنۍ کلام۔ {تہٕ} ٹوبیاہ ٲس میہ خوفس منز تراونہ خاطرہ چِٹھۍ سوزمژ۔ {الفاظ: یا، معاملہ}","1. وۅنۍ سپد یہ ییلہ دیوار بناونہ آو، تہٕ میہ ٲس دروازٕ لگٲومٕژ، تہٕ قلی تہٕ گیون وٲلۍ تہٕ لاوی مقرر کرنہٕ،\n2.\\tیُس میہ پننِس بٲیِس حنانی تہٕ حنانیاہ یُس محلُک حاکم اوس، یروشلمس پیٹھ دِژمُت، تکیازِ سُہ اوس اکھ وفادار انسان، تہٕ اوس خدایس سٍتـ̡ واریاہن کھوتہٕ زیادٕ کھوژان۔\n3.\\tتہٕ میہ ووٚن تِمن زِ یروشلمٕکۍ دروازٕ گژھن نہٕ یۄتام آفتاب گرم گژھہِ۔ تہٕ یێلہِ یێلہِ تِم کھڑا گژھن، دروازٕ بند کٔرِتھ، تہٕ یِمن ہٕندِس گرس مَنٛز تھاوُن تہٕ یِمن ہٕندِس گَھرس مُطٲبِق۔\n4.\\tوۅنۍ اوس شہر {بوٚڈ تہٕ عظیم}: مگر لوکھ ٲسۍ اتھ منز کم، تہٕ مکانہٕ ٲسۍ نہٕ بناونہٕ آمٕتۍ۔ {بٔڑ: ہیب۔ سپیس منز وسعت}\n5. تہٕ میانہِ خدایہ تھوو میٲنِس دِلس مَنٛز رئیس، حُکُمران تہٕ عوام یکجا کرنہٕ خٲطرٕ، یُتھ زن تِم شجرہ نسب سٍتـ̡ شمار کرنہٕ یِن۔ تہٕ مے لوٚب تِمن ہٕندِس شجرُک اکھ رجسٹر یُس گۅڈنچہ لٹہِ برونہہ کُن آو تہٕ اتھ منز لیکھِتھ لٔبِتھ،\n6. یِم چھِ صوبٕکۍ شُرۍ، یِم قٲد منزٕ نیبر نیرِمٕتۍ، یِم بابل کِس بادشاہ نبوکدنضرن نِتھ نِمٕتۍ، تہٕ دُبارٕ یروشلم تہٕ یہوداہ کُن آو، پرٮ۪تھ کانہہ اوس پننِس شہرس مَنٛز۔\n7.\\tیُس زروبابل، یشوع، نحمیا، عزریہ، رامیا، نہمانی، موردکی، بلشان، مسرتھ، بیگوای، نہوم، بعناہ سٍتـ̡ آو۔ {بہٕ چُھس ونان}، بنی اسرائیل کین انسانن ہند تعداد {یہ}؛ {عزریہ: تہِ ونان سریعہ}\n8.\\tپروش سٕندِ شُرۍ، زٕ ساس ہتھ ستتھ تہٕ زٕ۔\n9.\\tشیفتیاہ سٕندِ شُرۍ، ترے ہتھ ستتھ تہٕ زٕ۔\n10.\\tآرہ سٕندِ شُرۍ، شیہ ہتھ پنژاہ تہٕ زٕ۔\n11.\\tیشوع تہٕ یوآب سٕندِس شُرین ہٕندِس بُرۍ، زٕ ساس ٲٹھ ہتھ تہٕ ارداہ۔\n12.\\tایلام سٕندِ شُرۍ، ساس زٕ ہتھ تہٕ ژور۔\n13.\\tزٹو سٕندِ شُرۍ، ٲٹھ ہتھ ژتٲجی تہٕ پانژَہ۔\n14.\\tزکایی سٕندِ شُرۍ، ستھ ہتھ ترےٚ۔\n15.\\tبِنوئی سٕندِ شُرۍ، شیہ ہتھ ژتٲجی تہٕ ٲٹھ۔ {بِنوئی: بَنی تہِ وَننہٕ یِوان}\n16.\\tبیبایی ہٕندِ شُرۍ، شیہ ہتھ وُہُن تہٕ ٲٹھ۔\n17.\\tازگاد سٕندِ شُرۍ، زٕ ساس تریہ ہتھ تہٕ زُوہ۔\n18.\\tاڈونیکمٕکۍ شُرۍ، شیہ ہتھ ترے تہٕ ستھ۔\n19.\\tبِگویی سٕندِ شُرۍ، زٕ ساس ترے تہٕ سَتھ۔\n20.\\tعدین سٕندِ شُرۍ، شیہ ہتھ پنژاہ تہٕ پانژ۔\n21.\\tحزقیاہ سٕندِ آٹر سٕندِ شُرۍ، نتھ تہٕ ٲٹھ۔\n22.\\tہاشم سٕندِ شُرۍ، ترے ہتھ اٹھووہ۔\n23.\\tبیزایی سٕندِ شُرۍ، تریہ ہتھ تہٕ ژۅوُن۔\n24.\\tحاریف سٕندِ شُرۍ، اکھ ہتھ بارہ۔ {حارف: جورا تہِ ونان چھِ}\n25.\\tگبیون سٕندِ شُرۍ، نَمتھ تہٕ پانٛژ۔ {گِبیون: گِبَر تہِ ونان چھِ}\n26. بیت اللحم تہٕ نیٹوفاہٕکۍ مرد، اکھ ہتھ ژور تہٕ ٲٹھ۔\n27.\\tانتھوتھٕکۍ مرد، اکھ ہتھ تہٕ اٹھووہ۔\n28.\\tبیتھازماویت سٕندِ مرد، ژتٲجی تہٕ زٕ۔ {بیتھازماوتھ: یتھ تہِ ونان چھِ، ازماویتھ}\n29.\\tکرجاتجیریم، چیفیرہ تہٕ بیروتھٕکۍ مرد، ستھ ہتھ ژتٲجی تہٕ ترۍ۔ {کِرجاتھجیرِم: کِرجاتھرِم تہِ وَننہٕ یِوان}\n30.\\tرامہ تہٕ گیبا ہٕندِ مرد، شیہ ہتھ وُہُہ تہٕ اکھ۔\n31.\\tمِخماسٕکۍ مرد، اکھ ہتھ تہٕ زُو۔\n32.\\tبیتھل تہٕ آیی ہٕندِ مرد، ہتھ وُہُن تہٕ ترہ۔\n33.\\tبییِس نیبو ہٕندِ مرد، پنژاہ تہٕ زُو۔\n34.\\tبییِس ایلام سٕندِ شُرۍ، اکھ ساس زٕ ہتھ پنژاہ تہٕ ژور۔\n35.\\tحریم سٕندِ شُرۍ، ترے ہتھ وُہ۔\n36.\\tیریحہ سٕندِ شُرۍ، ترے ہتھ ژتٲجی تہٕ پانژٕ۔\n37.\\tلود، حدید تہٕ اونو سٕندِ شُرۍ، ستھ ہتھ وُہ تہٕ اکھ۔\n38.\\tسیناہٕکۍ بچہٕ، ترے ساس نو ہتھ تہٕ۔\n39. پادٕرۍ: یشع سٕندِ گرٕکۍ یِدایاہ سٕندِ بچہٕ، نَو ہتھ ستتھ تہٕ ترےٚ۔\n40.\\tاِمر سٕندِ شُرۍ، ساس پنژاہ تہٕ زٕ۔\n41.\\tپاشار سٕندِ شُرۍ، اکھ ساس زٕ ہتھ تہٕ ست۔\n42.\\tحریم سٕندِ شُرۍ، ساس سدہ ۔\n43.\\tلاوی: یشوع سٕندِ اولاد، کادمیێل سٕندِ شُرۍ، تہٕ ہودیوا سٕندِ شُرۍ، ستتھ تہٕ ژوٗر۔ {ہودیواہ: یتھ ہوداہ یا یہوداہ تہِ ونان چھِ}\n44.\\tگیون والۍ: آصف سٕندِ شُرۍ، اکھ ہتھ ژتٲجی تہٕ ٲٹھ۔\n45.\\tقلی: شالوم سٕندِ شُرۍ، آٹر سٕندِ شُرۍ، تلمون سٕندِ شُرۍ، عکوب سٕندِ شُرۍ، حتیطہ ہٕندِ شُرۍ، شوبایی ہٕندِ شُرۍ، ہتھ ترٕہ ٲٹھ۔\n46.\\tنیتھینیم: زیحہ سٕندِ شُرۍ، ہشوفہ سٕندِ شُرۍ، تباوت سٕندِ شُرۍ،\n47. کیروس سٕندِ شُرۍ، سِیا سٕندِ شُرۍ، پیڈون سٕندِ شُرۍ،\n48.\\tلبنان ہٕندِ بچہٕ، حجابہ سٕندِ شُرۍ، شلمایی ہٕندِ بچہٕ،\n49.\\tحنان سٕندِ بچہٕ، گِڈل سٕندِ بچہٕ، گَہر سٕندِ بچہٕ،\n50.\\tریعیاہ سٕندِ شُرۍ، ریزن سٕندِ شُرۍ، نیکوڈہ سٕندِ شُرۍ،\n51.\\tغزامہ سٕندِ اولاد، عزا سٕندِ اولاد، فسیح سٕندِ اولاد۔\n52.\\tبیسایی سٕندِ شُرۍ، میونِم سٕندِ شُرۍ، نیفیشیسم سٕندِ شُرۍ،\n53.\\tبکُک بچہٕ، ہکوفہ سٕندِ شُرۍ، ہرہر سٕندِ شُرۍ،\n54.\\tبزلِتھ سٕندِ شُرۍ، مہدہ سٕندِ شُرۍ، ہرشہ سٕندِ شُرۍ،\n55.\\tبارکوس سٕندِ شُرۍ، سیسیرا سٕندِ شُرۍ، تامہ سٕندِ شُرۍ،\n56.\\tنیضیہ سٕندِ بچہٕ، حتیفہ سٕندِ اولاد۔\n57.\\tسُلیمان سٕندٮ۪ن خادمَن ہٕندِ شُرۍ: سوتایی ہٕندِ شُرۍ، سوفیرتھ سٕندِ شُرۍ، پیریڈا سٕندِ شُرۍ،\n58.\\tجالا سٕندِ شُرۍ، ڈارکون سٕندِ شُرۍ، گِڈل سٕندِ شُرۍ،\n59. شیفطیہ سٕندِ بچہٕ، حتیل سٕندِ شُرۍ، زیبیمٕکۍ پوچیرتھ سٕندِ شُرۍ، آمون سٕندِ اولاد۔ {امون: امی تہِ ونان چھِ}\n60.\\tسٲری نیتھینم تہٕ سلیمان سٕندٮ۪ن خادمَن ہٕندِ شُرۍ، ٲسۍ تریہ ہتھ تہٕ زٕ۔\n61.\\tتہٕ یِم ٲسۍ تِم یِم تلمیلہ، تلہاریشہ، کروب، اڈون تہٕ اِمر پیٹھٕ تہِ ہیوٚت، مگر تِم ہیوٚک نہٕ پننِس مٲلہِ سُند گرٕ ہٲوِتھ، تہٕ نہ تِم ہٲوِتھ تہٕ تِمن ہٕندِس بُلِس سٍتـ̡ ٲسِتھ، یێلہِ تِم أسـ̡ اِسرٲیلـ̡ سٍتـ̡ ٲسِتھ۔ {بیج: یا، پیڈیگری}\n62.\\tڈیلیاہ سٕندِ شُرۍ، توبیاہ سٕندِ شُرۍ، نیکوڈہ سٕندِ شُرۍ، شیہ ہتھ ژتٲجی تہٕ زٕ۔\n63.\\tتہٕ پادٕرین ہٕندِس شُرۍ: حبیہ ہٕندِ شُرۍ، کوز سٕندِ شُرۍ، برزیلائی سٕندِ شُرۍ، یِمو برزیلائی سٕنزِ کورِ ہٕنزِ زنانہٕ رٔٹِتھ تہٕ تِمن ہٕندِس ناوٕ سٍتـ̡ وننہٕ آمُت۔\n64.\\tیِمو کٔر تِمن ہُند درٕج یِم شجرہ نسب سٍتـ̡ شمار کرنہٕ آمٕتۍ ٲسۍ، مگر سُہ آو نہٕ لبنہٕ: لہذا آیہ تِم پادٕرۍ نِش دِنہٕ۔\n65.\\tتہٕ تِمن ووٚن تِمن زِ تِم گژھن نہٕ مقدس چیزن منز کھٮ۪ن، یوٚت تام نہٕ اُریم تہٕ تھمِم ہیتھ اکھ پادٕرۍ کھڑا سپدِ۔ {ترشتھا: یا، گورنر}\n66.\\tسورے جماعت ٲس یکوٹہ ژتٲجی تہٕ زٕ ساس تریہ ہتھ تہٕ تریہ ہتھ،\n67.\\tتہندٮ۪ن نوکرَن تہٕ تِہٕندٮ۪ن نوکرَن علاوٕ، یِمو سٍتـ̡ ستھ ساس ترہ ہتھ تہٕ ستھ تہٕ یِمن آسہٕ زٕ ہتھ ژتٲجی تہٕ گٮ۪ون واجنہِ زنانہٕ۔\n68.\\tتِہٕندِ گُرۍ، سَتھ ہتھ ترٕہ تہٕ شیے: تِہٕندِ خچر زٕ ہتھ ژتٲجی تہٕ پانژھ:\n۶۹.\\t﴿تِہٕندِس اونٹَس﴾ ژور ہتھ تہٕ پانژھ: شیہ ساس ستھ ہتھ وُہ گَر۔\n70.\\tتہٕ مٲلن ہٕندیو کینٛہو سردارو دِژ کامہِ خٲطرٕ۔ ترشتھَن دِیُت خزانَس ساس سۄنہٕ، پنٛژاہ بیسن، پانژھ ہتھ تہٕ ترٕہ پادٕرین ہٕنٛدۍ پَلَو۔ {کینٛہہ: ہیب۔ حصہ۔} {ترشتھا: یا، گورنر}\n71.\\tتہٕ باپَن ہٕندِس سردارس دِژ کامہِ ہٕندِس خزانس وُہ ساس ساس سۄنہٕ تہٕ زٕ ساس تہٕ زٕ ہتھ پاؤنڈ رۄپہٕ۔\n72.\\tتہٕ سُہ {سُہ} یُس باقٕے لوکو دِیُت {سُہ} وُہ ساس ڈرم سۄن، تہٕ زٕ ساس پاؤنڈ رۄپھ، تہٕ تریہ تہٕ ستھ پادٕرین ہٕندِ پلو۔\n73.\\tیِتھ کٔنۍ ٲسۍ پادٕرۍ، لاوی، تہٕ قُلی، تہٕ گیون والۍ، تہٕ لُکہٕ تہٕ نیتھینیم، تہٕ سارِنٕے اسرٲیل، پننین شہرن مَنٛز روزان۔ تہٕ ییلہ سٔتِم ریتھ آو اسرٲیلٕکۍ بچہٕ ٲسۍ پننین شہرن مَنٛز۔","1. تہٕ سٲری لوکھ جمع گٔیہِ أکِس شخصس سٍتـ̡ سڑکہِ منز یُس آبہٕ دروازس برونہہ کنہِ اوس۔ تہٕ تِمو کٔر عزرا سٕندِس کاتبَس سٍتـ̡ کتھ زِ سُہ اَننہٕ خٲطرٕ موسىٰ سٕنزِ شریعت ہٕنز کتاب یُس خداوند اسرٲیلِس حُکُم اوس دِژمُت۔\n2. تہٕ عزرا پادٕرۍ اوٚن سٔتِمہِ رٮ۪تہٕ کِس گۄڈنِکِس دۅہہٕ مردَن تہٕ زنانن ہٕندِس اجتماعس برونہہ کُن شریعت تہٕ سارِنٕے سٍتـ̡ بوزنہٕ یِنہٕ وٲلِس سٍتـ̡ ۔ {یہ...: ہیب۔ یُس بوزنس منز سمجھ آو}\n3.\\tتہٕ تٔمۍ پٔرِتھ سڑکہِ برونہہ کُن یُس صبحہ پیٹھٕ دوپہرس تام آبہٕ دروازس برونہہ کنہِ اوس، مردن تہٕ زنانن برونہہ کُن، تہٕ یِم سمجھان ٲسۍ۔ تہٕ سارِنٕے لُکن ہٕندِس کَن ٲسۍ شریعت کِس کتابس کُن توجہ دِوان۔ {پیٹھ...: ہیب۔ گاشہٕ پیٹھ}\n4. تہٕ عزرا کاتب اوس لٔکرِ ہٕندِس منبرس پیٹھ کھڑا، یُس تمو امہِ مقصدٕ خٲطرٕ بنوومُت اوس۔ تہٕ أمِس سٍتـ̡ اوس دٔچھنہِ اتھس پیٹھ متیتیا، تہٕ شیما، تہٕ انیاہ، تہٕ یوریجاہ، تہٕ ہلکیاہ تہٕ ماسیا کھڑا ۔ تہٕ تٔمۍ سٕندِس کھوورِ اتھس پیٹھ پدیہ تہٕ مشاعیل، تہٕ ملکیاہ، تہٕ ہاشوم، تہٕ ہشبدانا، زکریا تہٕ مشُلم۔ {پلپٹ...: ہیب۔ ٹاور آف ووڈ}\n5.\\tتہٕ عزرا کٔر سارِنٕے لُکن ہٕندِس نظرس منز کتاب کھولنہٕ۔ (تکیازِ سُہ اوس سارِنٕے لُکن پیٹھ؛) تہٕ ییلہ تٔمۍ یہِ کھول، سٲری لوٗکھ کھڑا گٔیہِ: {وُچھن: ہیب۔ اچھ}\n6. تہٕ عزرا ہن کٔر خداوند عظیم خدایہ سٕنز برکت۔ تہٕ سارِوٕے لُکو دِژ جواب، آمین، آمین، اَتھٕ تُلِتھ تہٕ تِمو کٔر کلہٕ نوٚمُت، تہٕ کٔرٕکھ خداوند سٕنز پوٗزا کٔرِتھ زمینس کُن۔\n7.\\tیشوع تہٕ بنی تہٕ شیربیاہ، جامین، عکوب، شبتھی، ہودیجہ، ماسیہ، کلیتا، عزریہ، یوزآباد، حنان، پیلاہ، تہٕ لاویو کٔر لوکن شریعت سمجُن: تہٕ لُکھ گٔیہِ پننہِ جایہِ کھڑے۔\n8.\\tتێلہِ پٔر تِمو کِتابہِ مَنٛز خدایہ سٕندِس شریعتس مَنٛز واضح پٲٹھۍ، تہٕ دِتُکھ معنی تہٕ دِژُکھ تِمن پرُن سمجھان۔\n9.\\tتہٕ نحمیاہ یُس ترشتھا چُھ، تہٕ عزرا پادٕر، کاتب تہٕ لاوی یِمو لُکن ہیچھناوان اوس، سارنٕے لُکن ووٚن زِ یہِ دۅہ چُھ خداوند تُہندِ خدایہ سٕندِ خٲطرٕ پاک۔ نہ کرو ماتم تہٕ نہ روُن۔ تکیازِ سارِنٕے لُکھ رووُن، ییٚلہِ تِمو شریعتٕکۍ کلام بوزۍ۔ {ترشتھا: یا، گورنر}\n10.\\tتێلہِ ووٚن تِمن وَتہِ پٔکِو، چربی کھیوٚن تہٕ مِٹھایہِ چِھہ، تہٕ تِمن خٲطرٕ سوزُن تِمن ہُند حصہٕ یِمن ہٕندِ خٲطرٕ کانہہ تہِ تیار چُھہ نہٕ: کیازِ {یہ} دۅہ چُھہ سٲنِس آغہٕ سٕندِ خٲطرٕ پاک: تہٕ نہٕ گژھ افسوس تہٕ۔ تکیازِ خداوند سٕنز خوشی چِھ تُہند طاقت۔\n11.\\tیێلہِ کۆر لاویو سارِنٕے لُکھ رُکاونہٕ تہٕ وونُن، یێلہِ دۅہہٕ {چُھ} مقدس چُھ۔ نہ گژھہِ غم۔\n12.\\tتہٕ سارِوٕے لُکھ گٔیہِ کھٮ۪نہٕ خٲطرٕ، چیٚنہٕ خٲطرٕ، تہٕ حصہٕ سوزنہٕ خٲطرٕ، تہٕ سٮ۪ٹھاہ خوشی کرنہٕ خٲطرٕ، تِکیازِ تِمو ٲسۍ تِمن کُن اعلان کرنہٕ آمٕتۍ لفظ سمجِمٕتۍ۔\n13.\\tتہٕ دۆیمہِ دۅہہ آیہ سارنٕے لُکن ہٕندِس مٲلِس سٍتـ̡ پادٕرۍ تہٕ لاوی سٍتـ̡ شریعتٕکۍ کلام سمجھنہٕ خٲطرٕ عزرا کاتب سٕندِس نِش جمع کرنہٕ۔ {سمجھنہٕ خٲطرٕ...: یا، تاکہ تم ہیکن شریعت کین الفاظن منٛز ہدایت دِتھ}\n14. تہٕ تِمو وُچھ شریعت مَنٛز لیکھِتھ یُس خداوند موسىٰ سُند حکم اوس دِتمُت، زِ اسرٲیلٕکۍ بنی سٔتِم ریتہٕ کِس عیدس مَنٛز روزن بوتھن مَنٛز: {by: Heb. اتھہٕ سٍتۍ }\n15.\\tتہٕ یہ زِ تِم گژھن پننین سارنٕے شہرن تہٕ یروشلمس مَنٛز شایع کرنہٕ تہٕ اعلان کرُن، تہٕ گژھن پہاڑس کُن نیرُن، تہٕ زیتونٕچ لنجہِ، تہٕ دٲیرٕچ لنجہِ، تہٕ کھجورٕچ لنجہِ، تہٕ گٔنٮ۪ن کُلٮ۪ن ہٕنزِ لنجہِ أنِن، یِتھ کٔنۍ {یہِ} لیکھنہٕ آمُت چھُ۔\n16.\\tیێمہِ لُکھ درٛاو تہٕ أنِتھ تہٕ بَنووُکھ پرٮ۪تھ أکِس گَرٕ کِس چھتس پیٹھ، تہٕ تِمن ہٕندِس دربارس منز، تہٕ خدایہ سٕندِس گَرٕ کِس دربارس منز، تہٕ آبہٕ کِس دروازس مَنٛز، تہٕ افرائیم سٕندِس دروازٕ کِس سڑکہِ مَنٛز۔\n17.\\tتہٕ یِمو سارِنٕے جمٲژ یُس قٲد منزٕ دُبارٕ دُبارٕ دِنہٕ آمُت اوس، تِمو بِہتھ بوتھَن تَل بِہتھ، تکیازِ یشوع سٕندِ دۅہہٕ پیٹھٕ اوس نہٕ اَمہِ دۅہس تام بنی اسرٲیلِیو یہِ کٔرمٕژ۔ تہٕ اتہِ ٲس واریاہ خوشی۔\n18.\\tتہِ دۅہہ دۅہہ پٔرِتھ اوس سہ خدایہ سٕنزِ شریعت کِس کتابہِ منز پٔرِتھ۔ تہٕ تِمو تھوو سَتھ دۄہ دعوت۔ تہٕ ٲٹھمہِ دۅہہ اوس اکھ سنجیدہ مجلس، طریقہٕ مطٲبق۔ {اکھ سنجیدہ...: ہیب۔ اکھ پابندی}","1. وۅنۍ آیہ امہِ ریتہٕ کِس ژوٗروُہمہِ دۅہس منز بنی اسرائیلٕکۍ روزٕ تہٕ بوری پوشہٕ تہٕ زمینہِ ہٕندِس سٍتـ̡ جمع کرنہٕ۔\n2.\\tتہٕ اسرٲیلٕچ اولادٕ کٔر سارِنٕے اجنبی نِش الگ تہٕ کھڑا گٔیہِ تہٕ پننین بابن ہٕندِس گناہوں ہُند اقرار کٔرِتھ۔ {اجنبی: ہیب۔ عجیب شُرۍ}\n3.\\tتہٕ تِم ووٚتھ پننہِ جایہِ تھوٚد، تہٕ پٔرِکھ خداوند سٕندِس خدایہ سٕنزِ شریعت کِس کتابہِ مَنٛز دۅہہٕ کِس ژوٗرِمِس حصس مَنٛز۔ تہٕ {بییِھ} ژوٗرِم حصہٕ کٔر تِمو اقرار تہٕ کٔرٕکھ خداوند پنُن خدا۔\n4. پَتہٕ ووٚتھ لیوی، یشوع تہٕ بانی، کادمیل، شبانیہ، بنی، شیربیاہ، بانی، {تہٕ} چنانانی ہٕندِس ہیرن پیٹھ، تہٕ وُچھُن بَڑِ آوازٕ سٍتـ̡ خداوند پننِس خداہس کُن۔ {ہیڑۍ: یا، scaffold}\n5. اَمہِ پَتہٕ لاوۍ، یشوع تہٕ کادمیل، بنی، ہشبنیاہ، شیربیاہ، ہودیجاہ، شیبانیہ، {تہٕ} پتھاحیاہ وۆن، ووٚن زِ کھڑا گژھ {تہٕ} خداوند پنُن خدایہ سُند ہمیشہ خٲطرٕ برکت دِن، تہٕ تُہند شاندار ناو گژھہِ بابرکت یُس سارِوٕے برکتس تہٕ تعریفس پیٹھٕ تھوٚد چھُ۔\n6. تو، {حتیٰ کہ} توہ، {چھُ} صرف خدا۔ ژے بنوو آسمان، آسمانُک آسمان، تہندِس سارِنٕے لشکرس سٍتۍ، زمین، تہٕ سارِنٕے چیزن سٍتـ̡ یُس اتھ مَنٛز چُھ، سمندر، تہٕ اَتھ مَنٛز موجود سارِنٕے چیزن سٍتـ̡ تہٕ ژے چُھکھ تِمن سارِنٕے رٲچھ کٔرِتھ۔ تہٕ آسمانُک لشکر چُھ تۅہہِ عبادت کران۔\n7. تُہۍ چُھہ خداوند خدا، یٔمۍ ابرامُک انتخاب کوٚر، تہٕ أمِس کلدِیو منزٕ نِش نِش دِژُن تہٕ دِتُن تٔمِس ابراہیم سُند ناو۔\n8. تہٕ کورُن تٔمۍ سُند دِل پانس برونہہ کُن وفادار، تہٕ کورُن أمِس سٍتـ̡ عہد کورمُت زِ سُہ کٔرِن کنعانی، حتی، اموری تہٕ پیرزی، تہٕ یبوسی تہٕ گرگاشیتن ہٕنز زمین دِنہٕ خٲطرٕ، تہٕ کورُن تُہند کلام پورٕ۔ تۅہہ چُھہ نیک سٍتـ̡\n9.\\tتہٕ وُچھکھ مصرس منز سانین آباؤ اجدادن ہُند مصیبت تہٕ بحیرہ احمر کِس نِش تِہٕنز فریاد بوزمٕژ۔\n10.\\tتہٕ کٔرٕن فرعونس تہٕ تٔمۍ سٕندِس سارِنٕے خادمَن تہٕ تٔمۍ سٕندِس سارِنٕے لُکن ہٕندِس سٍتـ̡ نشانہٕ تہٕ عجائب ہاونہٕ، تکیازِ ژے ٲس پتاہ زِ تِمو کٔر تِمن سٍتـ̡ فخرٕ سٍتـ̡ سٍتـ̡ ۔ یِتھے پٲٹھۍ چھُکھ ژے اکھ ناو، یُتھ زن از تہِ چھُ۔\n11.\\tتہٕ ژے کٔر تِمن برونہہ کُن سمندرس منز تقسیم تہ تِم گٔیہِ خشک زمینس پیٹھ۔ تہٕ تِمن ہٕندِس ستٲمِس سٍتـ̡ ژٔٹِتھ ژٔٹِتھ ژٔٹِھتھ کٔرِ\n12.\\tتہِ چھکھ تِمن دۅہس اوٚبرِ تھمس سٍتۍ پکناوان۔ تہٕ رٲژ نارٕ کِس تھمَس سٍتۍ، تِمن تتھ وتہِ گاش دِنہٕ خٲطرٕ یُس تِم گژھن پَزِ۔\n13.\\tژے ووت سینا پہاڑس پیٹھ تہِ تہٕ آسمانہٕ پیٹھٕ تِمن سٍتـ̡ کتھ باتھ کٔرِتھ تہٕ دِژٕکھ تِمن سٍتـ̡ صحیح فیصلہٕ، تہٕ پٔزۍ قوانین، اصل قونونن تہٕ حُکمن دِژٕن: {صحیح...: حب۔ حقیقتک قوانین}\n14. تہٕ دیوانہٕ کٔرٕن تِمن تُہند مقدس سبت زان، تہٕ تِمن دِژُن تُہند خادم موسیٰ سٕندِ اتھہٕ سٍتـ̡ احکامات، قونونن تہٕ قونونن ہُند حُکُم۔\n15.\\tتہٕ دِژُن تِمن ہٕنزِ فاقہٕ خٲطرٕ آسمانہٕ سٍتـ̡ روٹی تہٕ تِمن ہٕندِ خٲطرٕ کٔرٕن کٔنہِ کٔنہِ آب تہٕ تِمن دِنُک وعدٕ کورُن زِ تِم گژھن سُہ زمینہٕ حٲصِل کرنہٕ خٲطرٕ یُس ژے تِمن دِنُک قسم اوس دِژمُت۔ {کُس...: ہیب۔ یُس ژے تِمن دِنہٕ خٲطرٕ پنُن اَتھٕ تُلِتھ اوس}\n16.\\tمگر تِمو تہٕ سانٮ۪و آباؤ اجدادو کٔر فخرٕ سٍتـ̡ تہٕ کٔرٕکھ نہٕ تُہٕندِس حُکمس سٍتـ̡ بوزنہٕ،\n17.\\tتہٕ کٔرٕن اطاعت کرنہٕ نِش انکار، تہٕ نہ ٲسٕکھ تِمن مَنٛز پنٕنۍ عجائب ہُند خیال تھاوان۔ مگر تِمن ہٕنزِ گردن کٔرٕکھ سخٕت تہٕ بغاوتس مَنٛز کوٚرُن تِمن ہٕنزِ غلامی منز واپس یِنہٕ خٲطرٕ اکھ کپتان مقرر: مگر تُہۍ چُھکھ اکھ خدایہ یُس معٲفی دِنہٕ خٲطرٕ تیار، مہربان تہٕ رحم دل چُھ، شرارتس منز سست تہٕ سٮ۪ٹھاہ مہربان تہٕ تِمن تراوُن نہٕ۔ {اکھ خدا...: ہیب۔ معافی ہند دیوتا}\n18.\\tآ، ییلہ تِمو تِمن پگلہٕ بَچھرٕ بَنوومُت تہٕ وونُن، یہِ چُھہ تُہند خدا یُس تۅہہِ مصرہٕ منزٕ نیبر کٔرِتھ تہٕ کورُن سٮ۪ٹھاہ اشتعال انگیز۔\n19.\\tتوتہِ چُھہ نہٕ تِم بیابانن مَنٛز تراوُن: اوٚبرُک تھَم چُھنہٕ تِمن نِش دۅہہٕ دۅہہٕ نیران، تہٕ تِمن وتہِ وَتھ پٲٹھۍ۔ نہ رٲژ نارُک ستون، تِمن گاش ہاونہٕ خٲطرٕ، تہٕ کُنہِ وتہِ یِمن گژھن۔\n20.\\tژے دِژ پنُن نیک روح تہِ تِمن ہٕنزِ تعلیمہٕ دِنہٕ خٲطرٕ، تہٕ تِمن ہٕنزِ ترشہٕ خٲطرٕ آب دِیُن نہٕ۔\n21.\\tژتٲجی ؤری رودۍ تِمن بیابانن مَنٛز، {یێلہِ} تِمن ٲس نہٕ کُنہِ تہِ کٔمی۔ تِہندۍ پلو ٲسۍ نہ پرون تہ کھۅر ٲسۍ نہ پھۅپھ کٔرۍمٕتۍ۔\n22.\\tامہِ علاوٕ دِژ تِمن بادشٲہی تہٕ قومن تہٕ کٔرِکھ تِمن کونن مَنٛز تقسیم۔\n23.\\tتِہٕندِس شُرِ تہِ کٔرِکھ اسمانٕکۍ ستارٕ سٍتـ̡ تہٕ أنِتھ تِمن زمینس مَنٛز، یێمہِ مُتلق ژے پننین مٲلن سٍتـ̡ وعدٕ کورمُت اوس زِ تِم گژھن اتھ پیٹھ قبضہ کرنہٕ خٲطرٕ۔\n24.\\tیێلہِ گٔیہِ شُرۍ اژِتھ زمینس پیٹھ قبضہ تہٕ ژے کٔرِکھ تِمن برونہہ کُن زمینہٕ کین روزن وٲلۍ، کنعانی، تہٕ تِم دِژن تِمن ہٕندِس اتھس منز، پننین بادشاہن تہٕ زمینہٕ کین لوکن سٍتۍ، یُتھ تِم یِمن سٍتـ̡ یِمن س {یتھ کٔنۍ تِم...: ہیب۔ تہنزِ مرضی مطٲبق}\n25.\\tتہٕ تِمو رٔٹِتھ مضبوٗط شہر، تہٕ اکھ موٚٹۍ زمین، تہٕ سارِوٕے سامانہٕ سٍتـ̡ بٔرِتھ مکانہٕ، کۄرٕ کھننہٕ آمٕتۍ، انگورن ہٕندِس باغس تہٕ زیتونن ہٕندِس باغس تہٕ مٮ۪وٕ کُلۍ کٔرِتھ کٔرٕکھ واریاہ زیادٕ۔ {ویلز: یا، حوض} {پھل...: ہیب۔ کُلۍ کھیوٚن}\n26.\\tبہر حال گٔیہِ تِمو نافرمان، تہٕ کٔرٕکھ تۅہہِ خلاف بغاوت تہٕ تُہٕندِس شریعت کٔرِکھ تہٕ تُہٕندِس پیغمبرن مٲرِتھ یِمو تِمن خلاف گوٲہی دِژ، تہٕ تِمو کٔرٕکھ سٮ۪ٹھاہ اشتعال انگیز۔\n27. تێمہِ کِنۍ دِژ تِم تِمن دُشمن ہٕندِس اتھس مَنٛز، یِمو تِمن پریشان کٔرِتھ، تہٕ تِمن ہٕندِس مصیبت وِزِ ییلہ تِمو تۅہہِ کُن کُن کٔرِتھ، تہٕ تِمن ہٕندِس مُشکِلَس مَنٛز، تہٕ تِمن ہٕندِس مصیبت وِزِ تہٕ تِمن ہٕندِس دُشمن ہٕندِس اتھس مَنٛز دِنہٕ آمُت، تہٕ تِمن ہٕند تہٕ پننہِ واریاہ رحمتہٕ مطٲبق دِژ تِمن نجات دِنہٕ وٲلۍ، یِمو تِمن دُشمنن ہٕندِ اتھہٕ نِش بچٲو۔\n28.\\tمگر ییلہ تِمو آرام کٔرِتھ، تِمو کٔر تۅہہِ برونہہ کُن دُبارٕ بُرٕ، تێلہِ تروو تِمن ہٕندِس دُشمن ہٕندِس اتھس منز، یێلہِ تِمن ہٕندِس دُشمن ہٕندِس اتھس منز، یێلہِ تِمن ہٕندِس دُشمن ہٕندِس اتھس مَنٛز تہٕ تِمن ہٕندِس دُشمن ہٕندِس اتھس مَنٛز تہٕ تِمن ہٕندِس دُشمن ہٕندِس اتھس مَنٛز، تێلہِ گٔیہِ تِمن ہٕندِس دُشمن ہٕندِس اتھس منز، تێلہِ بوز تِمن ہٕندِس تہٕ واریاہ لٹہِ کٔر تِم پننہِ رحمتہٕ مطٲبق نجات دِنہٕ۔ {تِمو کوٚر ...: ہیب۔ تِم آیہ بُرٕ کرنہٕ خٲطرٕ واپس}\n29.\\tتہٕ کٔرٕن تِمن خلاف گوٲہی دِژٕن، یُتھ تہٕ تِمو کٔرٕکھ تِمن ہٕندِس حکمس سٍتـ̡ بوزنہٕ، بلکہ کٔرٕکھ تُہندین فٲصلن خلاف گۅناہ (یُس یێلہِ کانہہ انسان کرِ، سُہ روزِ تِمن مَنٛز روزُن؛) تہٕ کٔرٕکھ پھیُر تہٕ گردن سختی کٔرِتھ تہٕ بوزُن نہٕ۔ {پتھ کُن...: ہیب۔ تِمو دِژ پتھ کھسُن}\n30. توتہِ کٔر تِمن واریاہن ؤرین برداشت تہٕ پننین پیغمبرن منز کٔرٕکھ تِمن خلاف گوٲہی دِژٕن، توتہِ دِژ نہٕ تِمو بوزنہٕ، تێمہِ مۄکھٕ دِیُن تِم زمینن ہٕندِس لُکن ہٕندِس اتھس مَنٛز۔ {forbear...: Heb. تمن پیٹھ کٔرِو زیٹھہ} {منز...: ہیب۔ تہندٮ۪ن پیغمبرن ہٕندِس اتھس منز}\n31.\\tتوتہِ کٔر نہٕ پننہِ عظیم رحمتہٕ خٲطرٕ یِم پوٗرٕ پٲٹھۍ، تہٕ نہ ترٲوِکھ تِم ۔ تِکیازِ تُہۍ چھُکھ اکھ مہربان تہٕ رحم دل خدا۔\n32. تێمہِ وۆن، سٲنـ̡ خدا، یُس عظیم، طاقتور تہٕ خوفناک خدا، یُس عہد تہٕ رحمتُک عمل تھاوان چُھ، تێلہِ گژھہِ نہٕ سارِنٕے مصیبت ژے برونہہ کُن کم ظٲہر سپدٕن، یُس اسہِ پیٹھ، سانین بادشاہن پیٹھ، سانین بادشاہن پیٹھ، سانین پادرن پیٹھ، سانین پیغمبرن پیٹھ، سانین پیغمبرن پیٹھ، سانین بابن پیٹھ، تہٕ سانین بابن پیٹھ، تہٕ تہندین سارنٕے لوکن پیٹھ، یُس از تام اسہِ پیٹھ، سانین بادشاہن پیٹھ، سانین بادشاہن پیٹھ، سانین پیغمبرن پیٹھ، سانین بابن پیٹھ، تہٕ پننین سارنٕے لوکن پیٹھ آمُت چُھ۔ {پریشانی: ہیب۔ تھکاوٹ} {یہ...: ہیب۔ یُس اسہِ لوٚب}\n33.\\tیێلہِ تہِ چُھہ تُہۍ یُس اسہِ پیٹھ دِنہٕ آمُت چُھ، تُہۍ چھِو سُہ سُہ سٍتـ̡ انصاف کٔرِتھ یُس اسہِ سٍ تکیازِ ژے چھہ صحیح کٲم کٔرمٕژ، مگر اسہِ چھیہ بدکار کٲم کٔرمٕژ:\n34.\\tسانٮ۪و بادشاہن، سانٮ۪و بادشاہن، سانٮ۪و پادٕرۍ، تہٕ سانٮ۪و بابو چُھکھ تُہٕندِس حکمس تہٕ گوٲہی بوزمٕژ، یِمو سٍتـ̡ ژے تِمن خلاف گوٲہی دِژمٕژ۔\n35. تِکیازِ تِمو کٔر نہٕ تۅہہِ ہٕنزِ بادشاہتس مَنٛز، تہٕ تُہٕندِس بٔڈِس نیکی سٍتـ̡ یُس تہٕ تِمن برونہہ کُن دِژمُت چُھ، تێلہِ ہٕندِس بٔڈِس تہٕ موٚٹِس زمینس مَنٛز یُس تِمن برونہہ کُن دِژمُت چُھ، تێلہِ کٔرٕکھ نہٕ تِمو پنہٕ نِس بدکار کامہِ نِش پتھ کُن۔\n36.\\tوُچھو أسۍ از کل خادم تہٕ تتھ زمینہٕ خٲطرٕ یُس ژے سانین آباؤ اجدادن دِژمُت چھُ، یُس تٔمِس پھل تہٕ اَمہ ہُند اصل کھٮ۪نہٕ خٲطرٕ دِژمُت چھُ، وُچھِو أسۍ اَتھ مَنٛز خادم:\n37.\\tتہٕ امہ سٍتـ̡ چُھ تِمن بادشاہن ہُند سٮ۪ٹھاہ ہُریر سپدان یُس ژے سانہِ گۅنہٕ کِنہِ اسہِ پیٹھ مقرر کورمُت چُھ، تہٕ تِمن ہٕندِس جسمس تہٕ سانین چارواین پیٹھ تہٕ تِمن ہٕنزِ مرضی سٍتـ̡ چُھہ تِمن ہٕندِس مُصیبت سٍتـ̡ تہٕ أسـ̡ سٍت\n38.\\tتہٕ امہ سارِنٕے کِنۍ چھِ أسۍ اکھ {عہد} یقینی بناوان، تہٕ لیکھان {یہ}؛ تہٕ سانۍ شہزادہ، لاوی، {تہٕ} پادٕرۍ، مہرٕ کٔرِتھ {اتھ پیٹھ}۔ {مہر: ہیب۔ چھِ سیلنگس پیٹھ، یا، سیلڈ}","1.\\tوۅنۍ یِمو مُہر کٔرِتھ، نحمیا، ترشتھا، ہخالیاہ سُند نیچو، تہٕ زِدکیجاہ، {تِم...: حب۔ مہرَن پیٹھ} {ترشتھا: یا، گورنر}\n2. سریاہ، عزریہ، یرمیاہ\n3. پشور، اماریہ، ملچیجاہ،\n4. ہتوش، شیبانیہ، مالوچ،\n5. حریم، میرموتھ، عوبیہ،\n6. ڈینیئل، گِنیتھن، باروچ،\n7. مشُلَم، ابیجاہ، میجامین،\n8.\\tمازیہ، بلگائی، شمعیہ: یم ٲسۍ پادٕرۍ۔\n9. تہٕ لاوی: دۄشوے یشوع، عزانیاہ سُند نیچو، حناداد سٕندِس نیچوِس بِنُوئی کَدمِیل؛\n10.\\tتہٕ تِہٕندِس بٲے، شبانیہ، ہودیجاہ، کلیتا، پیلاہ، حنان،\n11.\\tمیچا، ریہوب، حشبیہ،\n12. زکر، شیربیاہ، شیبانیا،\n13. ہودیجاہ، بانی، بینینو۔\n14. عوامُک سردار؛ پَروش، پَہتھموآب، ایلام، زَتو، بنی،\n15. بنی، ازگد، بیبائی،\n16.\\tادونیاہ، بیگوائی، عدن،\n17. اٹر، حزکیجہ، آزور،\n18. ہودیجہ، ہاشم، بیزائی،\n19. حریف، اناتھوتھ، نیبائی،\n20. مگپیاش، مشُلَم، ہِزر،\n21. مشیزابیل، زادوک، جدوا،\n22.\\tپیلاطیہ، حنان، عنایاہ،\n23. ہوشیع، حنانیہ، حشوب،\n24. ہالوہیش، پیلیہا، شوبیک،\n25. رحم، حشبنہ، ماسیہ،\n26. تہٕ احیجاہ، حنان، عنان،\n27.\\tمالچ، حریم، بانہ۔\n28. تہٕ باقٕے لُکہٕ، پادٕرۍ، لاوی، قُلی، گیون والۍ، نیتھینیم، تہٕ تِم سارِنٕے یِمو خدایہِ سٕندِس شریعت سٍتـ̡ ملکن ہٕندِس لُکن نِش الگ کٔرۍمٕتۍ، تِمن ہٕنزِ زنانہٕ، تِہٕندِس نیٚچوِس تہٕ کورِ، پرٮ۪تھ أکِس سٍتـ̡ زان تہٕ سمجھ تھاوان۔\n29.\\tتِم چِھ پننین باین تہٕ پننین رئیسن سٍتـ̡ بد دعا کٔرِتھ، تہٕ حلف کٔرِتھ کٔرِکھ خدایہِ سٕندِس شریعتس مُطٲبِق پٔکِتھ، یُس موسىٰ سٕندِ خدایہِ سٕندِس بندس دِژمُت اوس، تہٕ خداوند سٕندِس سارِنٕے حُکمن تہٕ تٔمۍ سٕندِس فٲصلن تہٕ تٔمۍ سٕندِس قونونن ہٕندِس سارِنٕے حُکمن ہٕنز پابندی تہٕ انجام دِنہٕ خٲطرٕ۔ {by: Heb. اتھہٕ سٍتۍ }\n30.\\tتہٕ یہ زِ أسۍ کرو نہٕ پنٕنۍ کورِ زمینہٕ کین لوکن دِنہٕ، تہٕ تِمن ہٕنزِ کورِ پننین نیچوین ہٕندِ خٲطرٕ نِنہٕ۔\n31.\\tتہٕ {یێلہ} زمینٕکۍ لوٗکھ سبت دۅہہٕ کٕننہٕ خٲطرٕ سامان یا کانہہ چیز اَنِن، {یہ} أسۍ ہیوٚک نہٕ سبت دۅہہ، یا مقدس دۅہہٕ یِمن نِش ہیوٚن: تہٕ {یہ} أسۍ تراوِ سٔتِم ؤری تہٕ پرٮ۪تھ کانہہ قرضہٕ۔ {پرٮ۪تھ کُن...: ہیب۔ پرتھ اتھہٕ}\n32.\\tاسہِ کٔر اسہِ خٲطرٕ آرڈین، یُس پننِس خدایہ سٕندِ گرٕ سٕنزِ خدمتہٕ خٲطرٕ سالانہٕ سالانہٕ شیکلُک تریم حصہٕ وصول کرُن۔\n33.\\tروٹی ہٕندِ خٲطرٕ، تہٕ ماز دِنہٕ خٲطرٕ، تہٕ مُسلسل زٲلنہٕ خٲطرٕ، سبت دوہ، نوِ زونہِ ہٕندِ، مُقرر عیدن خٲطرٕ، تہٕ مقدس چیزن خٲطرٕ، تہٕ گۅنہٕ نذرانہٕ خٲطرٕ، یُس اسرٲیلِس خٲطرٕ کفارہ دِنہٕ خٲطرٕ، تہٕ سٲنِس خدایہ سٕندِ گرٕ سٕنزِ سارِنٕے کامہِ خٲطرٕ۔\n34.\\tتہٕ أسۍ کٔرِو کاہن، لاوِین تہٕ لُکن مَنٛز لٔکرِ ہٕندِس نذرانہ خٲطرٕ، یُس سانہِ خدایہ سٕندِس گرس مَنٛز اننہٕ مۅکھہٕ، یُس سٲنِس خدایہ سٕندِس گرس مَنٛز دِنہٕ آمُت چھُ، یُس شریعتس مَنٛز لیکھنہٕ آمُت چُھ:\n35.\\tتہٕ سانہِ زمینہِ ہٕندِس گۄڈنِکِس پھل، تہٕ سارِنٕے کُلِین ہٕندِس گۅڈنِکِس پھلُک پھل ؤری پتہٕ ؤری خداوند سٕندِس گرس تام اننہٕ خٲطرٕ:\n36.\\tتہِ چُھہ سانین نیچوین تہٕ سانین چارواین ہُند گۄڈنیُک زامُت، یُتھ زن شریعت مَنٛز لیکھنہٕ آمُت چُھ، تہٕ سانہِ کھورِ تہٕ سانہِ چاروٕنـ̡ ہٕندِس گۅڈنچہ اولاد، یُس سانہِ خدایہ سٕندِس گرس مَنٛز خدمت کران چُھ، تِمن پادٕرین نِش اننہٕ خٲطرٕ:\n37.\\tتہٕ یُس اسہِ پَنٕنـ̡ آٹُک گۅڈنیُک پھل تہٕ پنُن نذرانہ تہٕ پرٮ۪تھ قٕسمٕک کُلۍ، شرابُک تہٕ تیلُک پھل پادٕرین نِن، پننِس خدایہ سٕندِس گرٕ کِس خانس مَنٛز انُن۔ تہٕ سانہِ زمینہِ ہُند دسُہ دِنہٕ یُن لاوِین تام، یُتھ زِ یۅہے لاوی آسہِ سانہِ کاشتہ کین سارنٕے شہرن مَنٛز تہٕ دس۔\n38.\\tتہٕ پادٕرۍ یُس ہارون سُند نیچو آسہِ، یێلہِ لاوی تہٕ لاوی دسُہ دِنہٕ ییہِ۔\n39.\\tبنی اسرٲیلِس تہٕ لاوی سٕندِ اولادٕ اَنِن مکایہٕ، نوِ شرابُک تہٕ تیٖل ہُند نذر، یێلہِ مُقدس ہٕندِس بانہٕ تہٕ پادٕرۍ یِم خدمت کران چھِ، تہٕ بُلۍ تہٕ گیون وٲلۍ، تہٕ أسۍ تراوِ نہٕ پنُن خدایہ سُند گرٕ۔","1. تہٕ لوکن ہٕندِ حکمران ٲسۍ یروشلمس مَنٛز روزان: باقٕے لُکو تہِ کٔر لاٹری تہٕ، تاکہ دہو منزٕ اکھ یُس مقدس شہر یروشلمس مَنٛز روزنہٕ خٲطرٕ، تہٕ نَو حصہٕ {باقٕے} شہرن مَنٛز روزنہٕ خٲطرٕ۔\n2. تہٕ لوکو کٔر سارنٕے نفرن برکت یِمو پننہِ مرضی سٍتـ̡ یروشلمس مَنٛز روزنہٕ خٲطرٕ پیش کٔر۔\n3. وۅنۍ چھہِ یِم یُس یروشلمس مَنٛز روزان اوس، مگر یہوداہ کین شہرن مَنٛز اوس پرٮ۪تھ کانہہ پننِس شہرس مَنٛز روزان، اسرائیل، کادٕن، لیوی تہٕ نیتھینیم، تہٕ سلیمان سٕندٮ۪ن خادمَن ہٕندِ شُرۍ۔\n4. تہٕ یروشلمس منز ٲس یہوداہ کین بچن تہٕ بنیامین سٕندِس اولادس منز روزان۔ یہوداہ سٕندِس شُرین منز؛ عذیاہ سُند نیچو، زکریا سُند نیچو، پیریز کین بچن ہُند نیچو، شیفطیہ سُند نیچو، مہللیل سُند نیچو۔ {پیریز: تہِ ونان چھِ، فاریز}\n5.\\tتہٕ ماسیہ سُند نیچو باروخ سُند نیچو، کولہوزہ سُند نیچو، یُس زکریا سُند نیچو اوس، یُس شیلونی سُند نیچو اوس زکریا سُند نیچو۔\n6.\\tیروشلمس منز روزن وٲلس پیریز سٕندِ سٲری نیچوۍ ٲسۍ ژور ہتھ تریہ تہٕ ٲٹھ بہادر نفر۔\n7. تہٕ یِم {چِھ} بنیامین سٕندِ نیچوۍ۔ سلوٗ مشُلَم سُنٛد نیٚچُو، جود سُنٛد نیٚچُو، پدایاہ سُنٛد نیٚچُو، کولیاہ سُنٛد نیٚچُو، یِسیاہ سُنٛد نیٚچُو، یِسعیاہ سُنٛد نیٚچُو۔\n8.\\tتہٕ تٔمِس پتہٕ گبائی، سلائی، نو ہتھ وُہُہ تہٕ ٲٹھ۔\n9.\\tتہٕ زکری سُند نیچو جوئیل اوس تِہُند نگراں تہٕ یہوداہ سُند نیچو اوس شہرس پیٹھ دویِم۔\n10. پادٕرین منز: جِدِیاہ یُس جویاریب سُند نیچو جاچِن۔\n11.\\tسریاہ ہلکیا سُند نیچو، مشُلم سُند نیچو، زادوک سُند نیچو، میریوتھ سُند نیچو، احیتوبُک نیچو، اوس خدایہ سٕندِس گرُک حُکُمران۔\n12.\\tتہٕ تِہندِ بٲے یِمو گرٕچ کٲم کٔرِتھ ٲسٕکھ ٲٹھ ہتھ تہٕ زُوُہ: تہٕ عدایاہ یِروہام سُند نیچو، پیلالیاہ سُند نیچو، زکریا سُند نیچو، پاشوٗر سُند نیچو، ملکیا سُند نیچو۔\n13.\\tتہٕ تٔمۍ سٕندِ بٲے، باپَن ہُند سردار، زٕ ہتھ تہٕ ژتٲجی: تہٕ اماشایی سُند نیچو اَحسایی سُند نیچو، یُس میشِلموتھ سُند نیچو اوس، یُس اِمر سُند نیچو اوس،\n14.\\tتہٕ تِہٕندِ بٲے، بہادر نفر، ہتھ تہٕ اَٹھہٕ وُہُن: تہٕ تِہُند نگراں اوس زبدیل، یُس بٔڈۍ نفرن ہُند نیچو اوس۔ {نیچو...: یا، ہگڈولیم سُند نیچو}\n15.\\tلاوِین ہُند تہِ: شمیعہ ہشوب سُند نیچو، عزریکم سُند نیچو، ہشبیاہ سُند نیچو، بنی سُند نیچو۔\n16.\\tتہٕ شبتھایی تہٕ جوزآباد، یُس لاوِین ہٕندِس سردارس سٍتـ̡ خدایہ سٕندِس ظاہری کارٕبارس پیٹھ نظر تھاوان۔ {had...: Heb. اوس ختم گٔمُت}\n17.\\tتہٕ متانیاہ یُس زبدی سُند نیچو اوس، یُس زبدی سُند نیچو اوس، یُس عبادتس منز شُکرگزاری شروع کران اوس، تہٕ بکبوکیا اوس پننین باین منز دویم تہٕ عبدا اوس شموع سُند نیچو، یُس جلالُن نیچو اوس یُس جدوتون سُند نیچو۔\n18.\\tمقدس شہرس مَنٛز ٲسۍ سارِنٕے لاوی زٕ ہتھ ژور تہٕ ژور۔\n19.\\tامہ علاوہ ٲسۍ پورٹر، عکوب، تلمون تہٕ تِہندۍ بٲے یِم دروازٕ رٔٹِتھ ٲسۍ، ٲسۍ ہتھ ستتھ تہٕ زٕ۔ {دروازٕ: ہیب۔ گیٹس پیٹھ}\n20. تہٕ اسرائیلٕچ باقیات، پادٕرین تہٕ لاوِین ہٕنز باقیات، یہوداہ کین سارنٕے شہرن مَنٛز، پرٮ۪تھ کانہہ اوس پننہِ وراثتس مَنٛز۔\n21.\\tمگر نیتھینم ٲسۍ اوفیلس منز روزان: تہٕ زیہا تہٕ گِسپا ٲسۍ نیتھینیمس پیٹھ۔ {اوفیل: یا، ٹاور}\n22.\\tیروشلمس مَنٛز لاوِین ہُند نگراں تہِ اوس عُزی یُس بنی سُند نیچو اوس، یُس حشبہیاہ سُند نیچو اوس، یُس میخا سُند نیچو اوس۔ آصف سٕندٮ۪ن نیٚچوٮ۪ن مَنٛز ٲسۍ گیون والۍ خدایہ سٕندِس گرٕ کِس کاربارس مَنٛز کٲم کٔرِتھ۔\n23.\\tتِمن متعلق اوس بادشاہ سُند حُکُم زِ اکھ خاص حصہ گژھہِ گیون والین ہٕندِ خٲطرٕ آسُن، یُس پرٮ۪تھ دۅہس خٲطرٕ واجب آسہِ۔ {اکھ یقین...: یا، اکھ یقینی آرڈیننس}\n24.\\tتہٕ یُس یہوداہ سُند نیچو زیرہ سٕندِس اولادس منز، پتحیاہ اوس بادشاہ سٕندِس اتھہٕ سٍتـ̡ لُکن ہٕندِس سارِنٕے معاملس مَنٛز۔ {زرہ: یتھ زارہ تہِ ونان چھِ}\n25.\\tتہٕ گامن ہٕندِس کھہَس سٍتۍ، یہوداہ ہٕندٮ۪ن اولادَن ہٕندِس کِرجاتَربہٕ سٍتـ̡ تہٕ یِمن ہٕندِس گامَس مَنٛز، تہٕ یِمن ہٕندِس گامَن مَنٛز، تہٕ یِمن ہٕندِس گامَن مَنٛز، تہٕ یِمن ہٕندِس گامَس مَنٛز،\n26. تہٕ یشوعس منز، تہٕ مولاداہس منز، تہٕ بیت فیلیٹس پیٹھ،\n27.\\tتہٕ ہزارشوالس منز، تہٕ بیرشیبعس منز، تہٕ تِمن ہٕندِس گامن منز،\n28.\\tتہٕ زِکلاگس منز، تہٕ میکونہ تہٕ تِمن ہٕندِس گامن منز،\n29.\\tتہٕ اینریمونس منز، تہٕ زریہ تہٕ جرموتھس منز،\n30.\\tزنواہ، عدللام تہٕ تِمن ہٕندِس گامس منز، لاچیش تہٕ تِمن ہٕندِس کھہَس منز، عزیقہ تہٕ تِمن ہٕندِس گامَس مَنٛز۔ تہٕ تِم ٲسۍ بیرشبع پیٹھٕ وادی ہنومس تام روزان۔\n31.\\tبنیامین سٕندِ شُرۍ تہِ گٔیہِ مِخماش، تہٕ آیجا، تہٕ بیتھلس مَنٛز، تہٕ تِہندین گامن مَنٛز، {منز: یا، of} {at: or, to}\n32. {تہٕ} انتھوتھ، نوب، انانیاہ،\n33.\\tحزور، رامہ، گیتایم،\n34. حدید، زیبویم، نبلاط،\n35. لوڈ، تہٕ اونو، کاریگرن ہٕنٛز وادی۔\n36.\\tتہٕ لاوِین ہٕندِس تقسیمس {منز} یہوداہ، {تہٕ} بنیامین منز۔","1. وۅنۍ چھہِ یم پادٕرۍ تہٕ لاوی یِم شیلٹیل سٕندِس نیچوِس زروبابلس سٍتـ̡ تہٕ یشوع سٍتـ̡ ہٕندِس سٍتـ̡ ووتـ̡\n2. اماریہ، ملُچ، ہتوش، {ملُچ: تہِ وَننہٕ یِوان، میلیکو}\n3.\\tشیخنیاہ، ریہوم، میرموتھ، {شیخانیاہ: تہِ ونان چھہِ، شیبانیا} {ریہوم: تہِ ونان چھہِ، حریم} {میرموتھ: تہِ ونان چھہِ}\n4. اِڈو، گنیتھو، ابیجاہ، {گنیتھو: یتھ گِنیتھون تہِ ونان چھِ}\n5. میامین، معادیہ، بلگاہ، {میامین: تہِ ونان چھِ، منیامین ﴾ {معادیہ: معادیہ تہِ ونان چھِ}\n6. شمعیہ، تہٕ جویاریب، جدیدیہ،\n7. سالو، اموک، ہلکیاہ، جدیاہ۔ یِم ٲسۍ یشوع سٕندِس زمانس مَنٛز پادٕرین تہٕ تِہندین باین ہٕندِس سردار۔ {سالو: تہٕ چُھ ونان، سلائی}\n8. یشوع، بِنوئی، کادمیئل، شیربیاہ، یہوداہ، {تہٕ} متانیا، {یُس} شُکرگزاری پیٹھ اوس، سُہ تہٕ تٔمۍ سٕندِس بٲے سٍتـ̡ ۔ {تھینکس گیونگ: یعنی تھینکس گیونگ ہند زبور}\n9.\\tبکیاہ تہٕ عُنی تہٕ تِہٕندِس بٲے تہِ گٔیہِ تِمن خٕلاف گَرِ مَنٛز۔\n10. تہٕ یشوع زاو جویاکیم، جویاکیمن تہِ پیوو الیاشیب، تہٕ الیاشیبن دیت جویادا،\n11.\\tتہٕ جویاداہن زٲو جوناتھن تہٕ جوناتھن زاو جدوا۔\n12.\\tتہٕ جویاکیٖم سٕندِس زمانس مَنٛز ٲسۍ پادٕرۍ، باپَن ہُند سردار: سرایاہُک، میرایہ۔ یرمیاہ ، حنانیاہ سُند۔\n13.\\tعزرا، مشُلم۔ اماریہ، جہوہان؛\n14. میلیکو، جوناتھن۔ شیبانیاہ، جوزف۔\n15.\\tحریم، عدنا۔ میریوتھ، ہیلکائی؛\n16. اِدو، زکریا سٕندِ۔ گِنیتھن، میشُلم؛\n17. ابیاہ، زکری۔ منیامین ، موڈیاہ، پلتائی۔\n18.\\tبلگاہ، شموعہ۔ شیمایاہ، یہوناتھن؛\n19. تہٕ جویاریب، مٹینائی۔ جدیاہ، عزی؛\n20.\\tسلائی، کالائی؛ اموک، ایبر؛\n21. حَلِقیاہ ہٕندِس حشبہَس مَنٛز۔ جدیدیہ، نیتھانیل۔\n22.\\tالیاشیب، جویادا، تہٕ جوحنان تہٕ جدوع سٕندِس زمانس مَنٛز ٲسۍ لاوی فادرن ہٕندِس سردارس منز درٕج کٔرۍمٕتۍ: پادٕرۍ تہِ، داریوش فارسی سٕندِس دورس تام۔\n23. لیوی سٕندِ نیچوۍ، یُس مٲلن ہُند سردار اوس، اوس تواریخ کِس کتابہِ منز لیکھنہٕ آمُت، یوتام زِ الیاشیب سٕندِس نیچوِس یوحنان سٕندِس زمانس تام۔\n24.\\tلاوِین ہُند سردار: حشبہ، شیربیاہ تہٕ یشوع یُس کادمیل سُند نیچو تہٕ یشوع یِمن ہٕندِس خٕلافس سٍتـ̡ تِمن ہٕندِس خٕلافس سٍتـ̡ حمد کرنہٕ خٲطرٕ، تہٕ خدا سٕندِ انسان سٕندِس حُکمس مُطٲبق چُھہ شُکر ادا کرنہٕ خٲطرٕ۔\n25.\\tمتانیہ، بکبوکیا، عوبدیہ، مشُلم، تلمون، عکوب، {ٲس} پورٹر یِم دروازن ہٕندِس دروازس پیٹھ وارڈ تھاوان۔ {حد: یا، خزانہٕ، یا، اسمبلی}\n26.\\tیِم ٲسۍ یشوع سٕندِس نیچوِس یویاقیم سٕندِس زمانس منز، یُس یوزادک سُند نیچو اوس، تہٕ نحمیاہ سٕندِس زمانس مَنٛز تہٕ پادٕرۍ عزرا سٕندِس زمانس مَنٛز، یُس کاتب اوس۔\n27. تہٕ یروشلمٕچ دیوار وقف کرنہٕ وِزِ ژھانڈ تِمو لاوی پنٕنـ̡ سارِنٕے جاین منز، یِمن یروشلم نِنہٕ خٲطرٕ، شُکرگزاری سٍتـ̡ تہٕ گیونہٕ سٍتـ̡ تہٕ گٮ۪ونہٕ سٍتـ̡ تہٕ چُھہ تِمن ہٕندِس سٍتـ̡ وقف کرنہٕ خٲطرٕ۔\n28.\\tتہٕ گیون والٮ۪ن ہٕندۍ نیچوۍ گٔیہِ یروشلمس اندۍ پکھۍ میدانی مُلکہٕ منزٕ تہٕ نیتوفتھی کین گامن منزٕ جمع ۔\n29.\\tگلگل کِس گرٕ پیٹھٕ تہٕ گیبا تہٕ عزماویت کِس کھہَو منزٕ تہٕ یِمن ہٕندِس اندۍ پٔکھۍ ٲسۍ یِمن ہٕندِس اندۍ پٔکھۍ گام بنوومٕتۍ۔\n30.\\tتہٕ پادٕرۍ تہٕ لاوی کٔر پان پاک تہٕ لوک، دروازٕ تہٕ دیوار پاک۔\n31.\\tاَمہ پتہٕ اوٚن میہ یہوداہ کِس شہزادس دیوارس پیٹھ، تہٕ مُقرر کٔرِتھ زٕ بٔڈۍ جمٲژ یِمو شُکریہ ادا کٔرِتھ، {یێمہِ سٍتـ̡ اکھ گۆو دٔچھنِس اتھس پیٹھ دیوارس پیٹھ گُرِ دروازس کُن:\n32.\\tتہٕ تِمن پَتہٕ دراو ہوشیا تہٕ یہوداہ ہٕکۍ نصف شہزادہٕ،\n33.\\tتہٕ عزریہ، عزرا تہٕ مشُلم،\n34. یہوداہ، تہٕ بنیمن، تہٕ شمعیاہ تہٕ یرمیاہ\n35.\\tتہٕ پادٕرین ہٕندِس نیچوِس سٍتـ̡ بُنـ̡ سٍتـ̡ {یعنی}، زکریا یوناتھن سُند نیچو، شیمعیاہ سُند نیچو، متانیاہ سُند نیچو، میکائیاہ سُند نیچو، زکورُن نیچو، یُس اساف سُند نیچو اوس۔\n36.\\tتہٕ تٔمۍ سٕندِس بٲے شمعیاہ تہٕ عزرایل، ملالایی، گیلالای، مائی، نیتھنیل تہٕ یہوداہ، حنانی، خدایہ سُند انسان داؤد سٕندِ موسیقی ہٕندِس سازس سٍتۍ، تہٕ عزرا سُند کاتب تہٕ تِمن برونہہ کُن کاتب۔\n37.\\tتہٕ فوارہ کِس دروازس پیٹھ، یُس تِمن خلاف اوس، تِم گٔیہِ داؤد شہر کِس ہیرن پیٹھ، دیوارٕ کِس ہیرِ پیٹھ، داؤد سٕندِس گرس پیٹھ، حتیٰ کہ مشرقس کُن آبہٕ کِس دروازس تام۔\n38.\\tتہٕ یِمن ہُند دوٚیِم جملہٕ یُس شُکر ادا کٔرِتھ گٔیہ، تہٕ بہٕ گۆو تِمن پَتہٕ تہٕ دیوارس پیٹھ نٮ۪صف لُکھ بُٹھہٕ کِس مینار پیٹھٕ بٔڈِس دیوارس تام۔\n39.\\tتہٕ افرائیم سٕندِ دروازٕ پیٹھ، تہٕ پرانہِ دروازٕ پیٹھ، تہٕ گاڈٕ دروازٕ پیٹھ، تہٕ حنانیل کِس مینارس پیٹھ، تہٕ میاح کِس مینارس تام، تہٕ تِم ٲسۍ قٲد خانہٕ کِس دروازس تام کھڑا۔\n40.\\tیِتھے پٲٹھۍ کھڑا یِمو خدایہ سٕندِس گرس مَنٛز شُکر ادا کٔرِتھ، تہٕ بہٕ تہٕ نصف حُکُمران ٲسۍ میہ سٍتۍ:\n41. تہٕ پادٕرۍ۔ الیاقیم، ماسیاہ، منیامین ، میکایا، ایلیونی، زکریا ، {تہٕ} حنانیاہ ، بُرگول سٍتۍ۔\n42.\\tتہٕ ماسیہ، تہٕ شمعیہ، تہٕ الیعازر، تہٕ عزی، تہٕ یہوہانان، تہٕ ملکیجاہ، تہٕ ایلام، تہٕ ایزر۔ تہٕ گلوکارو گیو بَڑِ پٲٹھۍ، یِزریاہ {تِہٕندِ} نگرانَس سٍتۍ۔ {گیو...: ہیب۔ تہنز آواز بوزنہٕ خٲطرٕ بنوو}\n43.\\tتمہِ دۅہہ تہِ کٔر تِمو سٮ۪ٹھاہ قربانی، تہٕ خۅش کٔرٕن: کیازِ خداین ٲس تِم سٮ۪ٹھاہ خوشی سان خۅش کٔرمٕژ، زنانہٕ تہٕ شُرۍ تہِ گٔیہِ خۅش، یُتھ زن یروشلمٕچ خوشی دوٗر تہِ بوزنہٕ۔\n44.\\tتہٕ تمہِ وِزِ ٲسۍ خانن پیٹھ کینہہ مقرر کرنہٕ آمٕتۍ، خزانہٕ خٲطرٕ، نذرانہٕ خٲطرٕ، گوڈنِکِس پھلہٕ خٲطرٕ، تہٕ دسمہٕ خٲطرٕ، یِمن منز شہرن ہٕندِس کھہَو منزٕ پادٕرین تہٕ لاوِین ہٕندِ خٲطرٕ شریعت ہٕندِ حِصہٕ جمع کرنہٕ خٲطرٕ، کیازِ یہوداہ اوس پادٕرین تہٕ لاوِین ہٕندِ خٲطرٕ شاد سپدان۔ {قانونُک: یعنی قانونہٕ کہِ ذریعہٕ مقرر کرنہٕ} {یہوداہ خٲطرٕ...: ہیب۔ یہوداہ سٕنزِ خوشی خٲطرٕ} {انتظار: ہیب۔ کھڑا}\n45.\\tتہٕ دۅشوے گیون والیو تہٕ قلیو تھوو داؤد سٕندِ حُکمہٕ مُطٲبق پننِس خدایہ سُند تہٕ پاکیزگی ہُند رٲچھ تھاوُن۔\n46. تکیازِ داؤد تہٕ آصاف سٕندِس زمانس مَنٛز ٲسۍ گیون والین ہٕندِس سردار، تہٕ خدایہ سٕندِ حمد تہٕ شُکرگزاری ہٕندِ بٲتھ آسان۔\n47.\\tتہٕ سارِنٕے اسرٲیلَن دِژ زروبابیل کِس دۅہس مَنٛز، تہٕ نحمیاہ کِس دۅہَس مَنٛز، گٮ۪ون والٮ۪ن تہٕ قُلٮ۪ن ہُند حصہٕ دِیُت، تہٕ تِمو کٔر لاوِین خٲطرٕ مقدس چیز۔ تہٕ لاویو کٔر ہارون سٕندِس بچن خٲطرٕ پاک۔ {مقدس: یعنی الگ الگ تھاوُن}","1. اَمہِ دۅہہٕ ٲسۍ تِمو موسیٰ سٕنزِ کتابہِ مَنٛز لُکن ہٕندِس سامعینَس مَنٛز پٔرِتھ۔ تہٕ اتھ منز آو لیکھنہٕ آمُت زِ امونائی تہٕ موآبی گژھن نہٕ ہمیشہٕ خٲطرٕ خدایہ سٕنزِ جماعتس منز یِن۔ {تِم...: ہیب۔ اَتھ اوس پٔرِتھ} {سامعین: Heb. کَن}\n2. تِکیازِ تِمو سمکھے نہٕ بنی اِسرٲیلِس روٹی تہٕ آبہٕ سٍتـ̡ ، بٔلکہِ تِمن خٕلاف کٔرِکھ بَلام رٔٹِتھ ، یُس سُہ تِمن لعنتَس مَنٛز بدلاوُن۔\n3.\\tوۅنۍ سپد ییلہ تمو شریعت بوز، تِمو کٔر سارِنٕے رلہٕ مِلہٕ لٔگِس اسرٲیلِس نِش الگ کرنہٕ۔\n4.\\tتہٕ امہِ برونہہ اوس الیاشیب، پادٕرۍ، یُس سانہِ خدایہ سٕندِس گرٕ کِس کمرس پیٹھ نظر تھاوان اوس، اوس توبیاہَس سٍتـ̡ رٔلِتھ: {ہاوُن...: حب۔ سیٹ اوور آسُن}\n5.\\tتہٕ تٔمۍ اوس تٔمِس خٲطرٕ اکھ بوٚڈ کمرٕ تیار کورمُت، یَتھ مَنٛز تِمو ماز ہٕندِس نذرانہٕ، لوبان تہٕ بانہٕ تہٕ مکایہِ ہُند دہہ، نوو شراب، تہٕ تیٖل دِنہٕ آمُت اوس، یُس لاوِین تہٕ گیون والٮ۪ن تہٕ قلین دِنُک حُکُم اوس دِنہٕ آمُت۔ تہٕ پادٕرین ہٕنز نذرانہٕ۔ {کُس...: ہیب۔ لاوِین ہُند حکم}\n6.\\tمگر اتھ سارِنٕے وقتس منز اوس نہٕ بہٕ یروشلمس منز، تکیازِ بابل کِس بادشاہ ارتخسرکس سٕندِس دۄن تہٕ ترہمہِ ؤریس مَنٛز آو بہٕ بادشاہس نِش، تہٕ کینژَن دۅہن پتہٕ ووت بہٕ بادشاہس نِش: {پتہٕ...: ہیب۔ دۅہن ہندِس ٲخرس پیٹھ} {حاصل...: یا، میہ کٔر سنجیدگی سان درخواست}\n7.\\tتہٕ بہٕ آو یروشلم، تہٕ سمجُن سُہ بُراے یُس الیاشیبن طوبیاہس خٲطرٕ کٔر، یُس خدایہ سٕندِس گرٕ کِس دربارس مَنٛز اکھ خانہٕ تیار کٔرِتھ اوس۔\n8.\\tتہٕ یہ گۆو میہ دگ دگ تہ تێلہِ کٔر میہ طوبیہ سُند سارِوٕے گرُک سامان خانہٕ منزٕ نیبر۔\n9. پَتہٕ دِیُت میہ حُکُم، تہٕ تِمو کٔر خانہٕ صاف تہٕ اَتہِ أنِتھ ماز تہٕ لوبان سٍتـ̡ دُبارٕ خدایہ سٕندِ گرٕکۍ بانہٕ۔\n10.\\tتہٕ میہ وُچھ زِ لاوِین ہٕندِ حِصہٕ چُھنہٕ دِنہٕ آمُت، تکیازِ لاوی تہٕ گیون والۍ، یِمو کٲم کٔرِتھ، ژٔلِکھ پرٮ۪تھ أکِس کھاہس کُن۔\n11.\\tاَمہِ پتہٕ کٔر میہ حکمرانن سٍتـ̡ بحث تہٕ وونُن، خدایہ سُند گرٕ کیازِ چُھہ تراونہٕ آمُت؟ تہٕ مے کٔر تِم جمع تہٕ تھووُن تِمن ہٕنزِ جایہ۔ {جاے: ہیب۔ سٹینڈنگ}\n12. پتہٕ أنِن سارِوٕے یہوداہ، مکایہِ ہُند حصہٕ تہٕ نوو شراب، تہٕ تیٖل خزانس مَنٛز۔ {خزانہٕ: یا، ذخیرٕ}\n13. تہٕ مے بنوو خزانن ہُند خزانہٕ، شیلمیاہ پادٕر، تہٕ صدوق کاتب تہٕ لاوِین ہُند تہٕ یِمن پَتہٕ اوس حنان یُس متانیاہ سُند نیچو زکور سُند نیچو اوس، تکیازِ تِم ٲسۍ وفادار ماننہٕ آمٕتۍ، تہٕ تِہُند عہدٕ اوس پننین باین منز بٲگراونہٕ خٲطرٕ۔ {خزانہٕ: یا، ذخیرٕ} {امہِ پتہٕ...: ہیب۔ تِمن ہٕندِس اتھس پیٹھ} {تِہُند دفتر...: ہیب۔ یہ اوس تمن پیٹھ}\n14. اے خدایہ، اتھ متعلقہٕ کٔرِو مے یاد تہٕ میٲنۍ نیک اعمال مٹٲوِو نہٕ یُس میہ پننِس خدایہ سٕندِس گرٕ خٲطرٕ تہٕ اَمہِ کِس عہدن خٲطرٕ کٔرمٕژ چھِ۔ {اصل...: ہیب۔ مہربانی} {دفتر: یا، مشاہدات}\n15.\\tتِمن دۅہن وُچھ میہ یہوداہَس مَنٛز سبت دۅہہٕ شرابُک دباو دِوان، تہٕ گُرٕ تہٕ گَرٕ أنِتھ وُچھمُت۔ تہٕ شراب، انگور تہٕ انجیر، تہٕ تمام {قسم} بوجھ، یُس تمو سبت کہ دوہ یروشلمس منٛز انان: تہٕ مے دژ تمن خلاف گوٲہی ییمہٕ دۅہہٕ تم کٕننہٕ آو۔\n16.\\tاَتھ منز ٲسۍ صور ہٕندِ نفر تہِ روزان، یِمو گاڈٕ تہٕ پرٮ۪تھ قٕسمُک سامان أنِتھ تہٕ سبت دۅہہٕ یہوداہ کِس شُرین تہٕ یروشلمس مَنٛز کٕننہٕ آمٕتۍ۔\n17. تێمہِ پَتہٕ کٔر میہ یہوداہ کین رئیسن سٍتـ̡ مُقابلہٕ، تہٕ تِمن وونُن، یہِ کیا بد کار چُھہ یُس تُہۍ کران چھِو، تہٕ سبت دۅہُک دۅہہٕ ناپاک کران چُھہ؟\n18.\\tکیا چُھہ نہٕ تۅہہِ بابو یِتھٕ پٲٹھۍ، تہٕ سٲنـ̡ خداین ہٲو نہٕ یێمہِ سٍتـ̡ یێلہ توتہِ چُھہ تُہۍ سبت دۅہہِ بے حرمتی کٔرِتھ اسرٲیلِس پیٹھ زیادٕ غصہٕ پٲدٕ کران۔\n19.\\tتہٕ سپُد یہِ زِ یێلہِ یێلہِ سبت دۅہہٕ برونہہ یِنہٕ یِنُک حُکُم تہٕ دِیُت میہ دِیُت زِ یِم گژھن نہٕ سبت دۅہہٕ پَتہٕ یِنہٕ۔\n20. یێمہِ کِنۍ گٔیہِ پرٮ۪تھ قٕسمٕک سامانہٕ کٕنَن وٲلہِ اَکہِ یا دۄیہِ لٹہِ یروشلم ورٲے روزنہٕ۔\n21.\\tاَمہ پتہٕ دِژ میہ تِمن خلاف گوٲہی تہٕ وونُن زِ ژیہ کیازِ چھِو دیوارس اندۍ پکھۍ روزان؟ اگر ژیہ بییہ تہِ کرِ، میہ تراوِ ژیہ اتھہ۔ تمہِ وقتہٕ پتہٕ آو نہٕ تِم سبت دۅہہٕ کُنہِ تہِ {زیادٕ}۔ {متعلق: ہیب۔ برٛونٛہہ}\n22. تہٕ مے دِیُت لاوِین حُکُم زِ تِم گژھن پنُن پان پاک کرُن، تہٕ یِم گژھن سبت دۅہہٕ پاک کرنہٕ خٲطرٕ یِن دروازٕ رژھرٕنۍ۔ اے میانہِ خدایہ، یہ تہِ یاد تھاوُن، تہٕ پننہِ رحمتہٕ ہٕندِ عظمتٕ مُطٲبق بچاو۔ {عظمت: یا، کثیر}\n23.\\tتِمن دۅہن تہِ وُچھ میہ یہودی {یُس} اَشدود سٕنز، عمونٕچ {تہٕ موآب﴾ سٕنزِ زنانہٕ سٍتـ̡ خاندر کٔرِتھ: {had...: Heb. تمن سٍتۍ روزُن اوس بنیومُت}\n24.\\tتہٕ تِہٕندِ شُرۍ ٲسۍ اَشدود سٕنزِ زبانہِ مَنٛز نصف کتھ کٔرِتھ، تہٕ تِم ٲسۍ نہٕ یہودین ہٕنزِ زبانہِ مَنٛز کتھ کٔرِتھ، بٔلکہِ پرٮ۪تھ لُکہٕ سٕنزِ زبانہِ مُطٲبِق۔ {کٔرِتھ...: ہیب۔ تِمو کٔر نہٕ کتھ کرنُک فِکر} {پرٮ۪تھ کُن...: ہیب۔ لوکن تہٕ لوکن ہُند}\n25.\\tتہٕ میہ کٔر تمن سٍتـ̡ لڑایہ، تہٕ تِمن ہٕندِس مَس ژٹِتھ تہٕ تِمن ہٕندِس مَس ژٹِتھ تہٕ تِمن ہُند قَسم کٔرُن خدایہِ سُند قسم۔ {لعنت: یا، ملامت کٔرتھ}\n26. کیا نہٕ اسرٲیلُک بادشاہ سلیمان یِمو سٍتـ̡ گۅناہ کورمُت؟ توتہِ اوس نہٕ واریاہن قومن مَنٛز أمِس ہیوٗ کانہہ بادشاہ، یُس پننِس خدایہ سُند محبوب اوس، تہٕ خداین بنوو سُہ سارِنٕے اسرٲیلِس پیٹھ بادشاہ، توتہِ اوس أمِس گۅنہٕ گۅنہٕ کٔرِتھ۔\n27. تیلہِ کیا أسۍ بوزو تۅہہِ یہ سورے بٔڈ بد کار کرنہٕ خٲطرٕ، یُس پننِس خدایس خلاف غیر ملکی زنانن سٍتۍ خانٛدر کٔرِتھ کٔرِتھ؟\n28.\\tتہٕ یویادا سٕندِس نیچوِس منز، یُس اعلیٰ پادٕرۍ الیاشیبُک نیچو اوس، یُس حورونی سنبلات سُند زامتُر اوس، اوے کٔر میہ پانس نِش پیچھا کرنہٕ۔\n29. اے خدایہ، تِم یاد تھاوُن، کیازِ یِمو چُھ پادٕرِی، تہٕ پادٕرِیُک تہٕ لاوِین ہُند عہد ناپاک کٔرِمُت۔ {کیازِ...: ہیب۔ ناپاک خٲطرٕ}\n30. یِتھٕ کٔنۍ کٔر مے تِم سارِنٕے غٲر ملکی نِش پاک، تہٕ کٔرٕن پادٕرین تہٕ لاوِین ہٕندِس رٲچھ مُقرر، پرٮ۪تھ أکِس سٕندِس کاروبارس مَنٛز۔\n31. تہٕ لٔکرِ ہٕندِس نذرانہ خٲطرٕ، کُنہِ ساتہٕ مقرر کرنہٕ آمُت، تہٕ گۄڈنِکِس پھلہٕ خٲطرٕ۔ اے خدایہ، میہ یاد تھاو اچھ خٲطرٕ۔"];
